contracts/core/AttestationRegistry.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";
import "@openzeppelin/contracts/utils/cryptography/MessageHashUtils.sol";

contract AttestationRegistry {
    using ECDSA for bytes32;

    struct AssetRecord {
        bytes32 assetId;
        bytes32 attestationHash;
        bytes32 blobId;
        address attestor;
        uint48 timestamp;
        bool revoked;
    }

    mapping(bytes32 => AssetRecord) public assets;
    mapping(address => bool) public trustedAttestors;
    address public owner;

    event AssetRegistered(bytes32 indexed assetId, bytes32 blobId, bytes32 attestationHash, address attestor);
    event AssetRevoked(bytes32 indexed assetId, string reason, uint256 timestamp);

    modifier onlyOwner() {
        require(msg.sender == owner, "Only owner");
        _;
    }

    constructor() {
        owner = msg.sender;
        trustedAttestors[msg.sender] = true;
    }

    function addTrustedAttestor(address attestor) external onlyOwner {
        trustedAttestors[attestor] = true;
    }

    function registerAsset(
        bytes32 assetId,
        bytes32 attestationHash,
        bytes32 blobId,
        bytes calldata payload,
        bytes calldata signature
    ) external {
        require(assets[assetId].timestamp == 0, "Asset already registered");
        require(keccak256(payload) == attestationHash, "Payload hash mismatch");

        // Recover signer from hash
        bytes32 ethSignedHash = MessageHashUtils.toEthSignedMessageHash(attestationHash);
        address recovered = ECDSA.recover(ethSignedHash, signature);

        require(trustedAttestors[recovered], "Invalid attestor signature");

        assets[assetId] = AssetRecord({
            assetId: assetId,
            attestationHash: attestationHash,
            blobId: blobId,
            attestor: recovered,
            timestamp: uint48(block.timestamp),
            revoked: false
        });

        emit AssetRegistered(assetId, blobId, attestationHash, recovered);
    }

    function revokeAsset(bytes32 assetId, string calldata reason) external onlyOwner {
        require(assets[assetId].timestamp > 0, "Asset not found");
        assets[assetId].revoked = true;
        emit AssetRevoked(assetId, reason, block.timestamp);
    }

    function isAssetValid(bytes32 assetId) external view returns (bool) {
        return assets[assetId].timestamp > 0 && !assets[assetId].revoked;
    }
}

contracts/core/ComplianceModule.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "./IdentityRegistry.sol";
import "./AttestationRegistry.sol";

contract ComplianceModule {
    IdentityRegistry public identityRegistry;
    AttestationRegistry public attestationRegistry;
    bytes32 public assetId;
    address public owner;

    modifier onlyOwner() {
        require(msg.sender == owner, "Only owner");
        _;
    }

    constructor(
        address _identityRegistry,
        address _attestationRegistry,
        bytes32 _assetId
    ) {
        owner = msg.sender;
        identityRegistry = IdentityRegistry(_identityRegistry);
        attestationRegistry = AttestationRegistry(_attestationRegistry);
        assetId = _assetId;
    }

    function canTransfer(address from, address to, uint256 /* amount */) external view returns (bool) {
        // 1. Check Sender KYC (unless minting/burning)
        if (from != address(0)) {
            if (!identityRegistry.isVerified(from)) return false;
        }

        // 2. Check Receiver KYC (unless burning)
        if (to != address(0)) {
            if (!identityRegistry.isVerified(to)) return false;
        }

        // 3. Check Asset Validity
        if (!attestationRegistry.isAssetValid(assetId)) return false;

        return true;
    }

    function setIdentityRegistry(address _identityRegistry) external onlyOwner {
        identityRegistry = IdentityRegistry(_identityRegistry);
    }

    function setAttestationRegistry(address _attestationRegistry) external onlyOwner {
        attestationRegistry = AttestationRegistry(_attestationRegistry);
    }
}

contracts/core/IdentityRegistry.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "./TrustedIssuersRegistry.sol";

contract IdentityRegistry {
    struct Identity {
        bool exists;
        bool isVerified;
        uint256 kycTimestamp;
        address wallet;
    }

    mapping(address => Identity) public identities;
    TrustedIssuersRegistry public trustedIssuersRegistry;
    address public owner;

    event IdentityRegistered(address indexed wallet, uint256 timestamp);
    event IdentityRemoved(address indexed wallet, uint256 timestamp);

    modifier onlyOwner() {
        require(msg.sender == owner, "Only owner");
        _;
    }

    modifier onlyTrustedIssuer() {
        require(trustedIssuersRegistry.isTrustedIssuer(msg.sender) || msg.sender == owner, "Only trusted issuer");
        _;
    }

    constructor(address _trustedIssuersRegistry) {
        owner = msg.sender;
        trustedIssuersRegistry = TrustedIssuersRegistry(_trustedIssuersRegistry);
    }

    function updateTrustedIssuersRegistry(address _newRegistry) external onlyOwner {
        trustedIssuersRegistry = TrustedIssuersRegistry(_newRegistry);
    }

    function registerIdentity(address wallet) external onlyTrustedIssuer {
        identities[wallet] = Identity({
            exists: true,
            isVerified: true,
            kycTimestamp: block.timestamp,
            wallet: wallet
        });
        emit IdentityRegistered(wallet, block.timestamp);
    }

    function removeIdentity(address wallet) external onlyTrustedIssuer {
        require(identities[wallet].exists, "Identity does not exist");
        identities[wallet].isVerified = false;
        emit IdentityRemoved(wallet, block.timestamp);
    }

    function batchRegisterIdentity(address[] calldata wallets) external onlyTrustedIssuer {
        for (uint256 i = 0; i < wallets.length; i++) {
            identities[wallets[i]] = Identity({
                exists: true,
                isVerified: true,
                kycTimestamp: block.timestamp,
                wallet: wallets[i]
            });
            emit IdentityRegistered(wallets[i], block.timestamp);
        }
    }

    function isVerified(address wallet) external view returns (bool) {
        return identities[wallet].isVerified;
    }

    function getIdentity(address wallet) external view returns (Identity memory) {
        return identities[wallet];
    }
}

contracts/core/PrivateAssetToken.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "./RWAToken.sol";

/**
 * @title PrivateAssetToken
 * @notice ERC-20 token representing physical/private assets (deeds, bonds, invoices, equipment)
 * @dev Extends RWAToken with additional metadata for private asset tracking
 *
 * Features:
 * - Inherits compliance and KYC from RWAToken
 * - Additional metadata: asset type, location, valuation, documents
 * - Platform mints 1 token = 1 physical asset
 * - Admin can update valuation with timestamp
 * - Document hash for off-chain verification (IPFS)
 */
contract PrivateAssetToken is RWAToken {
    // Asset metadata
    struct AssetMetadata {
        string assetType;        // "DEED", "BOND", "INVOICE", "EQUIPMENT", etc.
        string location;         // Physical location/jurisdiction
        uint256 valuation;       // USD value (6 decimals, e.g., 50000000000 = $50k)
        uint256 valuationDate;   // Timestamp of last valuation
        string documentHash;     // IPFS hash for legal documents
        bool isActive;           // Asset status
    }

    AssetMetadata public metadata;

    // Valuation history
    struct ValuationRecord {
        uint256 valuation;
        uint256 timestamp;
        address updatedBy;
    }

    ValuationRecord[] public valuationHistory;

    // Events
    event MetadataUpdated(
        string assetType,
        string location,
        string documentHash
    );
    event ValuationUpdated(
        uint256 oldValuation,
        uint256 newValuation,
        uint256 timestamp,
        address updatedBy
    );
    event AssetStatusChanged(bool isActive);

    /**
     * @notice Deploy PrivateAssetToken
     * @param _assetId Unique asset identifier (bytes32)
     * @param _compliance ComplianceModule address
     * @param _identityRegistry IdentityRegistry address
     * @param _totalSupply Total token supply (usually 1e18 for whole asset)
     * @param _platformCustody Platform custody address
     * @param _name Token name (e.g., "Property Deed #123")
     * @param _symbol Token symbol (e.g., "DEED123")
     * @param _issuer Issuer address
     * @param _assetType Asset type string
     * @param _location Physical location
     * @param _valuation Initial USD valuation (6 decimals)
     * @param _documentHash IPFS hash
     */
    constructor(
        bytes32 _assetId,
        address _compliance,
        address _identityRegistry,
        uint256 _totalSupply,
        address _platformCustody,
        string memory _name,
        string memory _symbol,
        address _issuer,
        string memory _assetType,
        string memory _location,
        uint256 _valuation,
        string memory _documentHash
    ) RWAToken(
        _assetId,
        _compliance,
        _identityRegistry,
        _totalSupply,
        _platformCustody,
        _name,
        _symbol,
        _issuer
    ) {
        require(_valuation > 0, "Valuation must be > 0");

        metadata = AssetMetadata({
            assetType: _assetType,
            location: _location,
            valuation: _valuation,
            valuationDate: block.timestamp,
            documentHash: _documentHash,
            isActive: true
        });

        // Record initial valuation
        valuationHistory.push(ValuationRecord({
            valuation: _valuation,
            timestamp: block.timestamp,
            updatedBy: msg.sender
        }));

        emit MetadataUpdated(_assetType, _location, _documentHash);
        emit ValuationUpdated(0, _valuation, block.timestamp, msg.sender);
    }

    /**
     * @notice Update asset metadata
     * @param _assetType New asset type
     * @param _location New location
     * @param _documentHash New document hash
     */
    function updateMetadata(
        string memory _assetType,
        string memory _location,
        string memory _documentHash
    ) external onlyOwner {
        metadata.assetType = _assetType;
        metadata.location = _location;
        metadata.documentHash = _documentHash;

        emit MetadataUpdated(_assetType, _location, _documentHash);
    }

    /**
     * @notice Update asset valuation
     * @param _newValuation New USD valuation (6 decimals)
     */
    function updateValuation(uint256 _newValuation) external onlyOwner {
        require(_newValuation > 0, "Valuation must be > 0");

        uint256 oldValuation = metadata.valuation;
        metadata.valuation = _newValuation;
        metadata.valuationDate = block.timestamp;

        // Record in history
        valuationHistory.push(ValuationRecord({
            valuation: _newValuation,
            timestamp: block.timestamp,
            updatedBy: msg.sender
        }));

        emit ValuationUpdated(oldValuation, _newValuation, block.timestamp, msg.sender);
    }

    /**
     * @notice Set asset active status
     * @param _isActive New status
     */
    function setActive(bool _isActive) external onlyOwner {
        metadata.isActive = _isActive;
        emit AssetStatusChanged(_isActive);
    }

    /**
     * @notice Get current valuation
     * @return Valuation in USD (6 decimals)
     */
    function getValuation() external view returns (uint256) {
        return metadata.valuation;
    }

    /**
     * @notice Get valuation history count
     * @return Number of valuation updates
     */
    function getValuationHistoryCount() external view returns (uint256) {
        return valuationHistory.length;
    }

    /**
     * @notice Get valuation record by index
     * @param index History index
     * @return ValuationRecord struct
     */
    function getValuationRecord(uint256 index) external view returns (ValuationRecord memory) {
        require(index < valuationHistory.length, "Index out of bounds");
        return valuationHistory[index];
    }

    /**
     * @notice Get complete asset metadata
     * @return AssetMetadata struct
     */
    function getMetadata() external view returns (AssetMetadata memory) {
        return metadata;
    }
}

contracts/core/RWAToken.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import "@openzeppelin/contracts/token/ERC20/extensions/ERC20Burnable.sol";
import "./ComplianceModule.sol";

contract RWAToken is ERC20, ERC20Burnable {
    bytes32 public assetId;
    ComplianceModule public compliance;
    address public identityRegistry;
    address public issuer;
    address public owner;
    bool public paused;

    modifier onlyOwner() {
        require(msg.sender == owner, "Only owner");
        _;
    }

    modifier whenNotPaused() {
        require(!paused, "Token paused");
        _;
    }

    constructor(
        bytes32 _assetId,
        address _compliance,
        address _identityRegistry,
        uint256 _totalSupply,
        address _platformCustody,
        string memory _name,
        string memory _symbol,
        address _issuer
    ) ERC20(_name, _symbol) {
        owner = msg.sender;
        assetId = _assetId;
        compliance = ComplianceModule(_compliance);
        identityRegistry = _identityRegistry;
        issuer = _issuer;

        _mint(_platformCustody, _totalSupply);
    }

    function _update(address from, address to, uint256 amount) internal virtual override {
        if (!paused && from != address(0) && to != address(0)) {
             require(compliance.canTransfer(from, to, amount), "Compliance check failed");
        }
        super._update(from, to, amount);
    }

    function forcedTransfer(address from, address to, uint256 amount) external onlyOwner {
        _transfer(from, to, amount);
    }

    function setPaused(bool _paused) external onlyOwner {
        paused = _paused;
    }

    function setCompliance(address _compliance) external onlyOwner {
        compliance = ComplianceModule(_compliance);
    }
}

contracts/core/SeniorPool.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

/**
 * @title SeniorPool
 * @notice USDC lending pool for leverage positions at 5% APR
 * @dev Provides USDC loans to LeverageVault for investor leverage purchases
 *
 * Features:
 * - USDC deposits from liquidity providers
 * - Loans with 5% APR interest accrual
 * - Liquidity reserve requirements (20-30%)
 * - Debt ceiling per position ($100k max)
 * - Interest compounding for demo mode
 */
contract SeniorPool is Ownable, ReentrancyGuard {
    IERC20 public usdc;
    address public leverageVault;
    address public solvencyVault;

    // Pool parameters
    uint256 public constant APR = 500; // 5% APR (basis points)
    uint256 public constant BASIS_POINTS = 10000;
    uint256 public constant DEBT_CEILING = 100_000 * 1e6; // $100k per position (USDC 6 decimals)
    uint256 public constant RESERVE_RATIO = 2000; // 20% reserve requirement (basis points)

    // Pool state
    uint256 public totalLiquidity; // Total USDC deposited
    uint256 public totalBorrowed; // Total USDC currently borrowed
    uint256 public totalInterestEarned; // Cumulative interest earned

    // Loan tracking
    struct Loan {
        uint256 principal; // Original loan amount
        uint256 interestAccrued; // Accumulated interest
        uint256 lastUpdateTime; // Last interest calculation timestamp
        bool active; // Loan status
    }

    mapping(uint256 => Loan) public loans; // positionId => Loan

    // Demo mode for accelerated time
    bool public demoMode;
    uint256 public timeMultiplier; // e.g., 360 for 360x acceleration

    // Events
    event LiquidityDeposited(address indexed depositor, uint256 amount);
    event LiquidityWithdrawn(address indexed withdrawer, uint256 amount);
    event LoanIssued(uint256 indexed positionId, uint256 amount);
    event LoanRepaid(uint256 indexed positionId, uint256 principal, uint256 interest);
    event InterestAccrued(uint256 indexed positionId, uint256 interest);
    event DemoModeUpdated(bool enabled, uint256 multiplier);

    modifier onlyAuthorizedVault() {
        require(
            msg.sender == leverageVault || msg.sender == solvencyVault,
            "Only authorized vault"
        );
        _;
    }

    /**
     * @notice Initialize Senior Pool
     * @param _usdc USDC token address
     */
    constructor(address _usdc) Ownable(msg.sender) {
        usdc = IERC20(_usdc);
        demoMode = false;
        timeMultiplier = 1;
    }

    /**
     * @notice Set LeverageVault address (one-time)
     * @param _leverageVault LeverageVault contract address
     */
    function setLeverageVault(address _leverageVault) external onlyOwner {
        require(leverageVault == address(0), "LeverageVault already set");
        require(_leverageVault != address(0), "Invalid address");
        leverageVault = _leverageVault;
    }

    /**
     * @notice Set SolvencyVault address (one-time)
     * @param _solvencyVault SolvencyVault contract address
     */
    function setSolvencyVault(address _solvencyVault) external onlyOwner {
        require(solvencyVault == address(0), "SolvencyVault already set");
        require(_solvencyVault != address(0), "Invalid address");
        solvencyVault = _solvencyVault;
    }

    /**
     * @notice Enable/disable demo mode for time acceleration
     * @param _enabled Enable demo mode
     * @param _multiplier Time multiplier (e.g., 360 for 360x)
     */
    function setDemoMode(bool _enabled, uint256 _multiplier) external onlyOwner {
        require(_multiplier > 0, "Multiplier must be > 0");
        demoMode = _enabled;
        timeMultiplier = _multiplier;
        emit DemoModeUpdated(_enabled, _multiplier);
    }

    /**
     * @notice Deposit USDC liquidity into pool
     * @param amount Amount of USDC to deposit (6 decimals)
     */
    function depositLiquidity(uint256 amount) external nonReentrant {
        require(amount > 0, "Amount must be > 0");

        require(
            usdc.transferFrom(msg.sender, address(this), amount),
            "USDC transfer failed"
        );

        totalLiquidity += amount;
        emit LiquidityDeposited(msg.sender, amount);
    }

    /**
     * @notice Withdraw USDC liquidity from pool
     * @param amount Amount of USDC to withdraw (6 decimals)
     */
    function withdrawLiquidity(uint256 amount) external onlyOwner nonReentrant {
        require(amount > 0, "Amount must be > 0");
        require(amount <= getAvailableLiquidity(), "Insufficient available liquidity");

        totalLiquidity -= amount;
        require(usdc.transfer(msg.sender, amount), "USDC transfer failed");

        emit LiquidityWithdrawn(msg.sender, amount);
    }

    /**
     * @notice Borrow USDC for leverage position
     * @param positionId Unique position identifier
     * @param amount Amount to borrow (6 decimals)
     */
    function borrow(uint256 positionId, uint256 amount) external onlyAuthorizedVault nonReentrant {
        require(amount > 0, "Amount must be > 0");
        require(amount <= DEBT_CEILING, "Exceeds debt ceiling");
        // Removed restriction: Users can open multiple positions
        // require(!loans[positionId].active, "Loan already exists");
        require(amount <= getAvailableLiquidity(), "Insufficient liquidity");

        // Create loan (or overwrite if exists - each position should have unique ID anyway)
        loans[positionId] = Loan({
            principal: amount,
            interestAccrued: 0,
            lastUpdateTime: block.timestamp,
            active: true
        });

        totalBorrowed += amount;

        // Transfer USDC to calling vault
        require(usdc.transfer(msg.sender, amount), "USDC transfer failed");

        emit LoanIssued(positionId, amount);
    }

    /**
     * @notice Repay loan (principal + interest)
     * @param positionId Position identifier
     * @param amount Amount to repay (6 decimals)
     * @return principal Principal repaid
     * @return interest Interest repaid
     */
    function repay(
        uint256 positionId,
        uint256 amount
    ) external onlyAuthorizedVault nonReentrant returns (uint256 principal, uint256 interest) {
        require(loans[positionId].active, "Loan not active");

        // Update interest before repayment
        Loan storage loan = loans[positionId];
        uint256 totalOwed = loan.principal + loan.interestAccrued;
        require(amount <= totalOwed, "Amount exceeds debt");


        // Calculate principal and interest portions
        if (amount <= loan.interestAccrued) {
            // Repaying only interest
            interest = amount;
            principal = 0;
            loan.interestAccrued -= interest;
        } else {
            // Repaying interest + principal
            interest = loan.interestAccrued;
            principal = amount - interest;
            loan.interestAccrued = 0;
            loan.principal -= principal;
        }

        // Update pool state
        totalBorrowed -= principal;
        totalInterestEarned += interest;
        totalLiquidity += interest; // Interest stays in pool

        // Transfer USDC from calling vault
        require(
            usdc.transferFrom(msg.sender, address(this), amount),
            "USDC transfer failed"
        );

        // Close loan if fully repaid
        if (loan.principal == 0) {
            loan.active = false;
        }

        _accrueInterest(positionId);

        emit LoanRepaid(positionId, principal, interest);
    }

    /**
     * @notice Get outstanding debt for position (principal + accrued interest)
     * @param positionId Position identifier
     * @return Outstanding debt amount
     */
    function getOutstandingDebt(uint256 positionId) external view returns (uint256) {
        if (!loans[positionId].active) return 0;

        Loan memory loan = loans[positionId];
        uint256 pendingInterest = _calculateInterest(positionId);
        return loan.principal + loan.interestAccrued + pendingInterest;
    }

    /**
     * @notice Get accrued interest for position
     * @param positionId Position identifier
     * @return Accrued interest amount
     */
    function getAccruedInterest(uint256 positionId) external view returns (uint256) {
        if (!loans[positionId].active) return 0;

        Loan memory loan = loans[positionId];
        uint256 pendingInterest = _calculateInterest(positionId);
        return loan.interestAccrued + pendingInterest;
    }

    /**
     * @notice Get available liquidity for lending
     * @return Available USDC amount
     */
    function getAvailableLiquidity() public view returns (uint256) {
        // Ensure reserve requirement is met
        uint256 requiredReserve = (totalBorrowed * RESERVE_RATIO) / BASIS_POINTS;
        uint256 available = totalLiquidity > totalBorrowed
            ? totalLiquidity - totalBorrowed
            : 0;

        return available > requiredReserve ? available - requiredReserve : 0;
    }

    /**
     * @notice Accrue interest for a loan
     * @param positionId Position identifier
     */
    function accrueInterest(uint256 positionId) external {
        require(loans[positionId].active, "Loan not active");
        _accrueInterest(positionId);
    }

    /**
     * @notice Internal: Accrue interest for a loan
     * @param positionId Position identifier
     */
    function _accrueInterest(uint256 positionId) internal {
        Loan storage loan = loans[positionId];
        uint256 interest = _calculateInterest(positionId);

        if (interest > 0) {
            loan.interestAccrued += interest;
            loan.lastUpdateTime = block.timestamp;
            emit InterestAccrued(positionId, interest);
        }
    }

    /**
     * @notice Internal: Calculate pending interest
     * @param positionId Position identifier
     * @return Pending interest amount
     */
    function _calculateInterest(uint256 positionId) internal view returns (uint256) {
        Loan memory loan = loans[positionId];
        if (!loan.active || loan.principal == 0) return 0;

        uint256 timeElapsed = block.timestamp - loan.lastUpdateTime;

        // Apply time multiplier for demo mode
        if (demoMode) {
            timeElapsed = timeElapsed * timeMultiplier;
        }

        // Interest = (principal * APR * timeElapsed) / (BASIS_POINTS * SECONDS_PER_YEAR)
        // APR is in basis points (500 = 5%)
        uint256 interest = (loan.principal * APR * timeElapsed) /
            (BASIS_POINTS * 365 days);

        return interest;
    }

    /**
     * @notice Get pool statistics
     * @return Total liquidity, total borrowed, available liquidity, total interest earned
     */
    function getPoolStats()
        external
        view
        returns (uint256, uint256, uint256, uint256)
    {
        return (
            totalLiquidity,
            totalBorrowed,
            getAvailableLiquidity(),
            totalInterestEarned
        );
    }
}

contracts/core/SolvencyVault.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

// SeniorPool interface
interface ISeniorPool {
    function borrow(uint256 positionId, uint256 amount) external;

    function repay(
        uint256 positionId,
        uint256 amount
    ) external returns (uint256 principal, uint256 interest);

    function getOutstandingDebt(uint256 positionId) external view returns (uint256);

    function getAccruedInterest(uint256 positionId) external view returns (uint256);
}

// PrimaryMarket interface for liquidation listings
interface IPrimaryMarket {
    enum ListingType { STATIC, AUCTION }

    function createListing(
        bytes32 assetId,
        address tokenAddress,
        ListingType listingType,
        uint256 priceOrReserve,
        uint256 duration,
        uint256 totalSupply,
        uint256 minInvestment
    ) external;
}

// OAID interface
interface IOAID {
    function issueCreditLine(
        address user,
        address collateralToken,
        uint256 collateralAmount,
        uint256 valueUSD,
        uint256 solvencyPositionId
    ) external returns (uint256 creditLineId);

    function revokeCreditLine(
        uint256 creditLineId,
        string memory reason
    ) external;

    function recordPayment(
        uint256 creditLineId,
        uint256 amount,
        bool onTime,
        uint256 daysLate
    ) external;

    function recordCreditUsage(
        uint256 creditLineId,
        uint256 amount
    ) external;

    function recordCreditRepayment(
        uint256 creditLineId,
        uint256 amount
    ) external;
}

// YieldVault interface
interface IYieldVault {
    function claimYield(address rwaToken, uint256 tokenAmount) external returns (uint256 usdcReceived);
}

/**
 * @title SolvencyVault
 * @notice Collateral vault for borrowing USDC against RWA tokens or Private Asset tokens
 * @dev Supports two token types with different LTV ratios and liquidation flows
 *
 * Normal Flow:
 * 1. User deposits RWA/PrivateAsset tokens as collateral
 * 2. Vault borrows USDC from SeniorPool based on LTV (70% for RWA, 60% for Private)
 * 3. If OAID enabled: Issues on-chain credit line for user
 * 4. User repays loan + interest (recorded in OAID payment history)
 * 5. User withdraws collateral after full repayment
 *
 * Liquidation Flows (health factor < 115%):
 * 
 * RWA Token Liquidation (Invoice-backed assets):
 * 1. liquidatePosition() - Marks position as liquidated, revokes OAID credit line
 * 2. Wait for invoice settlement/maturity
 * 3. settleLiquidation() - Burns RWA tokens for USDC yield via YieldVault
 * 4. Repay debt, take 10% fee, return excess to user
 * 
 * Private Asset Liquidation:
 * 1. liquidatePosition() - Marks liquidated, revokes OAID credit line
 * 2. Admin purchases collateral via purchaseAndSettleLiquidation()
 * 3. Admin sends USDC, receives Private Asset tokens
 * 4. Contract repays debt, takes 10% fee from excess, returns remainder to user
 *    (Admin can then do anything with the tokens - sell, hold, redistribute, etc.)
 */
contract SolvencyVault is Ownable, ReentrancyGuard {
    // Token types
    enum TokenType {
        RWA,            // RWA tokens from marketplace (70% LTV)
        PRIVATE_ASSET   // Private asset tokens (60% LTV)
    }

    // Position tracking
    struct Position {
        address user;               // Borrower address
        address collateralToken;    // Token address (RWA or PrivateAsset)
        uint256 collateralAmount;   // Token amount deposited (18 decimals)
        uint256 usdcBorrowed;       // USDC borrowed from SeniorPool (6 decimals)
        uint256 tokenValueUSD;      // Valuation at deposit time (6 decimals)
        uint256 createdAt;          // Position creation timestamp
        uint256 liquidatedAt;       // Liquidation timestamp (0 if not liquidated)
        uint256 creditLineId;       // OAID credit line ID (0 if not issued)
        bool active;                // Position status
        TokenType tokenType;        // RWA or PRIVATE_ASSET
    }

    // External contracts
    IERC20 public usdc;
    address public seniorPool;
    address public primaryMarket;
    address public oaid;            // Optional OAID integration

    // Position management
    mapping(uint256 => Position) public positions;
    uint256 public nextPositionId;

    // LTV and health parameters (basis points)
    uint256 public constant RWA_LTV = 7000;                     // 70%
    uint256 public constant PRIVATE_ASSET_LTV = 6000;           // 60%
    uint256 public constant LIQUIDATION_THRESHOLD = 11500;      // 115%
    uint256 public constant LIQUIDATION_FEE_BPS = 1000;         // 10% liquidation fee
    uint256 public constant BASIS_POINTS = 10000;

    // Liquidation tracking
    mapping(uint256 => bool) public positionsInLiquidation;     // positionId => liquidation status
    address public yieldVault;                                   // YieldVault contract for burning RWA tokens

    // Repayment Schedule
    struct RepaymentPlan {
        uint256 loanDuration;          // Total duration in seconds (e.g., 90 days)
        uint256 numberOfInstallments;  // Total installments (e.g., 18)
        uint256 installmentInterval;   // Duration of each interval (seconds)
        uint256 nextPaymentDue;        // Timestamp of next due date
        uint256 installmentsPaid;      // Counter
        uint256 missedPayments;        // Counter for missed/late payments
        bool isActive;                 // If plan is active
        bool defaulted;                // Marked as defaulted by admin
    }

    mapping(uint256 => RepaymentPlan) public repaymentPlans;

    // Events
    event PositionCreated(
        uint256 indexed positionId,
        address indexed user,
        address collateralToken,
        uint256 collateralAmount,
        uint256 tokenValueUSD,
        TokenType tokenType
    );
    event USDCBorrowed(
        uint256 indexed positionId,
        uint256 amount,
        uint256 totalDebt
    );
    event RepaymentPlanCreated(
        uint256 indexed positionId,
        uint256 loanDuration,
        uint256 numberOfInstallments,
        uint256 installmentInterval,
        uint256 nextPaymentDue
    );
    event LoanRepaid(
        uint256 indexed positionId,
        uint256 amount,
        uint256 principal,
        uint256 interest,
        uint256 remainingDebt
    );
    event MissedPaymentMarked(
        uint256 indexed positionId,
        uint256 missedPayments
    );
    event PositionDefaulted(
        uint256 indexed positionId
    );
    event CollateralWithdrawn(
        uint256 indexed positionId,
        address indexed user,
        uint256 amount
    );
    event PositionLiquidated(
        uint256 indexed positionId,
        uint256 liquidationTime
    );
    event LiquidationSettled(
        uint256 indexed positionId,
        uint256 yieldReceived,
        uint256 debtRepaid,
        uint256 liquidationFee,
        uint256 userRefund
    );
    event OAIDCreditIssued(
        uint256 indexed positionId,
        uint256 creditLineId,
        uint256 creditLimit
    );
    event CreditLineRevoked(
        uint256 indexed positionId,
        uint256 indexed creditLineId,
        string reason
    );
    event PrivateAssetLiquidationSettled(
        uint256 indexed positionId,
        address indexed purchaser,
        uint256 purchaseAmount,
        uint256 tokensTransferred,
        uint256 debtRepaid,
        uint256 liquidationFee,
        uint256 userRefund
    );

    /**
     * @notice Initialize Solvency Vault
     * @param _usdc USDC token address
     * @param _seniorPool SeniorPool contract address
     */
    constructor(
        address _usdc,
        address _seniorPool
    ) Ownable(msg.sender) {
        usdc = IERC20(_usdc);
        seniorPool = _seniorPool;
        nextPositionId = 1;
    }

    /**
     * @notice Set PrimaryMarket address
     * @param _primaryMarket PrimaryMarket contract address
     */
    function setPrimaryMarket(address _primaryMarket) external onlyOwner {
        require(_primaryMarket != address(0), "Invalid address");
        primaryMarket = _primaryMarket;
    }

    /**
     * @notice Set OAID address (optional)
     * @param _oaid OAID contract address
     */
    function setOAID(address _oaid) external onlyOwner {
        require(_oaid != address(0), "Invalid address");
        oaid = _oaid;
    }

    /**
     * @notice Set YieldVault address
     * @param _yieldVault YieldVault contract address
     */
    function setYieldVault(address _yieldVault) external onlyOwner {
        require(_yieldVault != address(0), "Invalid address");
        yieldVault = _yieldVault;
    }

    /**
     * @notice Deposit collateral tokens
     * @param collateralToken Token address (RWA or PrivateAsset)
     * @param collateralAmount Token amount (18 decimals)
     * @param tokenValueUSD Valuation in USD (6 decimals)
     * @param tokenType RWA or PRIVATE_ASSET
     * @param issueOAID Whether to issue OAID credit line
     * @return positionId Created position ID
     */
    function depositCollateral(
        address collateralToken,
        uint256 collateralAmount,
        uint256 tokenValueUSD,
        TokenType tokenType,
        bool issueOAID
    ) external nonReentrant returns (uint256 positionId) {
        require(collateralToken != address(0), "Invalid token");
        require(collateralAmount > 0, "Amount must be > 0");
        require(tokenValueUSD > 0, "Valuation must be > 0");

        // Transfer tokens from user to vault
        require(
            IERC20(collateralToken).transferFrom(msg.sender, address(this), collateralAmount),
            "Token transfer failed"
        );

        // Create position
        positionId = nextPositionId++;
        positions[positionId] = Position({
            user: msg.sender,
            collateralToken: collateralToken,
            collateralAmount: collateralAmount,
            usdcBorrowed: 0,
            tokenValueUSD: tokenValueUSD,
            createdAt: block.timestamp,
            liquidatedAt: 0,
            creditLineId: 0,
            active: true,
            tokenType: tokenType
        });

        emit PositionCreated(
            positionId,
            msg.sender,
            collateralToken,
            collateralAmount,
            tokenValueUSD,
            tokenType
        );

        // Issue OAID credit line if requested
        if (issueOAID && oaid != address(0)) {
            uint256 ltv = tokenType == TokenType.RWA ? RWA_LTV : PRIVATE_ASSET_LTV;
            uint256 creditLimit = (tokenValueUSD * ltv) / BASIS_POINTS;

            uint256 creditLineId = IOAID(oaid).issueCreditLine(
                msg.sender,
                collateralToken,
                collateralAmount,
                tokenValueUSD,
                positionId
            );
            // Store credit line ID in position
            positions[positionId].creditLineId = creditLineId;
            emit OAIDCreditIssued(positionId, creditLineId, creditLimit);
        }
    }

    /**
     * @notice Borrow USDC against collateral with repayment schedule
     * @param positionId Position ID
     * @param amount USDC amount to borrow (6 decimals)
     * @param loanDuration Total duration of the loan in seconds
     * @param numberOfInstallments Number of fixed installments
     */
    function borrowUSDC(
        uint256 positionId,
        uint256 amount,
        uint256 loanDuration,
        uint256 numberOfInstallments
    ) external nonReentrant {
        Position storage position = positions[positionId];
        require(position.active, "Position not active");
        require(msg.sender == position.user, "Not position owner");
        require(amount > 0, "Amount must be > 0");

        // Validate repayment terms
        require(loanDuration > 0, "Duration must be > 0");
        require(numberOfInstallments > 0, "Installments must be > 0");
        require(loanDuration >= numberOfInstallments, "Invalid duration/installments");

        // Ensure no existing plan for this position (or support refinancing later)
        require(!repaymentPlans[positionId].isActive, "Plan already active");

        // Calculate max borrowable amount based on LTV
        uint256 ltv = position.tokenType == TokenType.RWA ? RWA_LTV : PRIVATE_ASSET_LTV;
        uint256 maxBorrow = (position.tokenValueUSD * ltv) / BASIS_POINTS;
        uint256 newTotalBorrowed = position.usdcBorrowed + amount;

        require(newTotalBorrowed <= maxBorrow, "Exceeds LTV limit");

        // Calculate installment interval
        uint256 installmentInterval = loanDuration / numberOfInstallments;

        // Initialize RepaymentPlan
        repaymentPlans[positionId] = RepaymentPlan({
            loanDuration: loanDuration,
            numberOfInstallments: numberOfInstallments,
            installmentInterval: installmentInterval,
            nextPaymentDue: block.timestamp + installmentInterval,
            installmentsPaid: 0,
            missedPayments: 0,
            isActive: true,
            defaulted: false
        });

        // Borrow from SeniorPool
        ISeniorPool(seniorPool).borrow(positionId, amount);

        // Update position
        position.usdcBorrowed += amount;

        // Record credit usage in OAID if credit line exists
        if (oaid != address(0) && position.creditLineId > 0) {
            IOAID(oaid).recordCreditUsage(position.creditLineId, amount);
        }

        // Transfer USDC to user
        require(usdc.transfer(msg.sender, amount), "USDC transfer failed");

        emit USDCBorrowed(positionId, amount, position.usdcBorrowed);
        emit RepaymentPlanCreated(
            positionId,
            loanDuration,
            numberOfInstallments,
            installmentInterval,
            block.timestamp + installmentInterval
        );
    }

    /**
     * @notice Repay loan (principal + interest)
     * @param positionId Position ID
     * @param amount USDC amount to repay (6 decimals)
     */
    function repayLoan(uint256 positionId, uint256 amount) external nonReentrant {
        Position storage position = positions[positionId];
        require(position.active, "Position not active");
        require(msg.sender == position.user, "Not position owner");
        require(amount > 0, "Amount must be > 0");

        // Transfer USDC from user
        require(
            usdc.transferFrom(msg.sender, address(this), amount),
            "USDC transfer failed"
        );

        // Approve SeniorPool to take repayment
        usdc.approve(seniorPool, amount);

        // Repay to SeniorPool
        (uint256 principal, uint256 interest) = ISeniorPool(seniorPool).repay(
            positionId,
            amount
        );

        // Update position
        position.usdcBorrowed -= principal;

        uint256 remainingDebt = ISeniorPool(seniorPool).getOutstandingDebt(positionId);

        // Update Repayment Plan
        RepaymentPlan storage plan = repaymentPlans[positionId];

        if (plan.isActive) {
            // Increment installments paid
            plan.installmentsPaid++;

            // If fully repaid (based on debt, not installments count, as installments are estimated)
            if (remainingDebt == 0 || (plan.installmentsPaid >= plan.numberOfInstallments)) {
                plan.isActive = false;
            }
        }

        // Record payment in OAID if credit line exists
        if (oaid != address(0) && position.creditLineId > 0) {
            // Reduce credit used by principal amount
            if (principal > 0) {
                IOAID(oaid).recordCreditRepayment(position.creditLineId, principal);
            }

            IOAID(oaid).recordPayment(
                position.creditLineId,
                amount,
                true, // Always mark as on-time here; missed payments are marked by admin
                0
            );
        }

        emit LoanRepaid(positionId, amount, principal, interest, remainingDebt);
    }

    /**
     * @notice Withdraw collateral (requires full loan repayment)
     * @param positionId Position ID
     * @param amount Token amount to withdraw (18 decimals)
     */
    function withdrawCollateral(uint256 positionId, uint256 amount) external nonReentrant {
        Position storage position = positions[positionId];
        // require(position.active, "Position not active");
        require(msg.sender == position.user, "Not position owner");
        require(amount > 0, "Amount must be > 0");
        require(amount <= position.collateralAmount, "Insufficient collateral");

        // Verify no outstanding debt
        uint256 outstandingDebt = ISeniorPool(seniorPool).getOutstandingDebt(positionId);
        require(outstandingDebt == 0, "Outstanding debt must be repaid");

        // Update token valuation proportionally
        uint256 oldCollateral = position.collateralAmount;
        uint256 newCollateral = oldCollateral - amount;

        if (newCollateral == 0) {
            position.tokenValueUSD = 0;
        } else {
            position.tokenValueUSD = (position.tokenValueUSD * newCollateral) / oldCollateral;
        }

        // Update position
        position.collateralAmount = newCollateral;

        // Close position if fully withdrawn
        if (position.collateralAmount == 0) {
            position.active = false;
            if (repaymentPlans[positionId].isActive) {
                repaymentPlans[positionId].isActive = false;
            }

            // Revoke OAID credit line
            if (oaid != address(0) && position.creditLineId > 0) {
                IOAID(oaid).revokeCreditLine(position.creditLineId, "Collateral withdrawn");
            }
        }

        // Transfer tokens to user
        require(
            IERC20(position.collateralToken).transfer(msg.sender, amount),
            "Token transfer failed"
        );

        emit CollateralWithdrawn(positionId, msg.sender, amount);
    }

    /**
     * @notice Mark a missed payment (Admin only)
     * @param positionId Position ID
     */
    function markMissedPayment(uint256 positionId) external onlyOwner {
        Position storage position = positions[positionId];
        require(position.active, "Position not active");

        RepaymentPlan storage plan = repaymentPlans[positionId];
        require(plan.isActive, "Plan not active");

        plan.missedPayments++;

        // Record missed payment in OAID (0 amount, onTime=false)
        if (oaid != address(0) && position.creditLineId > 0) {
            IOAID(oaid).recordPayment(
                position.creditLineId,
                0,      // amount
                false,  // onTime (false = missed/late)
                1       // daysLate (placeholder)
            );
        }

        emit MissedPaymentMarked(positionId, plan.missedPayments);
    }

    /**
     * @notice Mark position as defaulted (Admin only)
     * @param positionId Position ID
     */
    function markDefaulted(uint256 positionId) external onlyOwner {
        Position storage position = positions[positionId];
        require(position.active, "Position not active");

        RepaymentPlan storage plan = repaymentPlans[positionId];
        require(plan.isActive, "Plan not active");

        plan.defaulted = true;

        emit PositionDefaulted(positionId);
    }

    /**
     * @notice Mark position for liquidation (health < 115% OR marked defaulted)
     * @param positionId Position ID
     * @dev Two flows:
     *      - RWA tokens: Mark for liquidation, wait for invoice settlement
     *      - Private Assets: Mark for liquidation, admin can purchase directly
     */
    function liquidatePosition(
        uint256 positionId
    ) external onlyOwner nonReentrant {
        Position storage position = positions[positionId];
        require(position.active, "Position not active");
        require(!positionsInLiquidation[positionId], "Already in liquidation");

        // Verify liquidation is necessary
        // 1. Health Factor Check (< 115%)
        uint256 healthFactor = getHealthFactor(positionId);
        bool healthLiquidatable = healthFactor < LIQUIDATION_THRESHOLD;

        // 2. Repayment Default Check (marked by admin)
        RepaymentPlan storage plan = repaymentPlans[positionId];
        bool defaultLiquidatable = plan.isActive && plan.defaulted;

        require(healthLiquidatable || defaultLiquidatable, "Position is healthy and not defaulted");

        // Mark position as liquidated (but keep active to hold tokens)
        positionsInLiquidation[positionId] = true;
        position.liquidatedAt = block.timestamp;

        // Deactivate repayment plan
        if (plan.isActive) {
            plan.isActive = false;
        }

        // Revoke OAID credit line if exists
        if (oaid != address(0) && position.creditLineId > 0) {
            string memory reason = healthLiquidatable 
                ? "Position liquidated - collateral health below threshold"
                : "Position liquidated - repayment default";

            IOAID(oaid).revokeCreditLine(
                position.creditLineId,
                reason
            );

            emit CreditLineRevoked(
                positionId,
                position.creditLineId,
                reason
            );
        }

        emit PositionLiquidated(positionId, block.timestamp);
    }

    /**
     * @notice Process liquidation settlement by burning RWA tokens for yield
     * @param positionId Position ID
     * @dev Called after RWA settlement - burns tokens, repays loan, takes 10% fee, returns excess
     *      Only for RWA token collateral
     */
    function settleLiquidation(
        uint256 positionId
    ) external onlyOwner nonReentrant returns (uint256 yieldReceived, uint256 liquidationFee, uint256 userRefund) {
        Position storage position = positions[positionId];
        require(position.active, "Position not active");
        require(positionsInLiquidation[positionId], "Position not liquidated");
        require(position.tokenType == TokenType.RWA, "Only for RWA tokens");
        require(yieldVault != address(0), "YieldVault not set");

        // Approve YieldVault to burn RWA tokens
        IERC20(position.collateralToken).approve(yieldVault, position.collateralAmount);

        // Get USDC balance before
        uint256 balanceBefore = usdc.balanceOf(address(this));

        // Burn RWA tokens to claim USDC yield using low-level call (no return value expected)
        (bool success, ) = yieldVault.call(
            abi.encodeWithSignature(
                "claimYield(address,uint256)",
                position.collateralToken,
                position.collateralAmount
            )
        );
        require(success, "YieldVault claim failed");

        // Calculate USDC received
        uint256 balanceAfter = usdc.balanceOf(address(this));
        yieldReceived = balanceAfter - balanceBefore;
        require(yieldReceived > 0, "No yield received");

        // Get outstanding debt
        uint256 outstandingDebt = ISeniorPool(seniorPool).getOutstandingDebt(positionId);

        uint256 debtRepaid = 0;

        if (outstandingDebt > 0) {
            // Repay as much debt as possible
            uint256 repaymentAmount = yieldReceived > outstandingDebt
                ? outstandingDebt
                : yieldReceived;

            usdc.approve(seniorPool, repaymentAmount);
            ISeniorPool(seniorPool).repay(positionId, repaymentAmount);
            debtRepaid = repaymentAmount;
        }

        // Calculate liquidation fee and user refund from excess
        if (yieldReceived > debtRepaid) {
            uint256 excess = yieldReceived - debtRepaid;

            // Calculate 10% liquidation fee
            liquidationFee = (excess * LIQUIDATION_FEE_BPS) / BASIS_POINTS;
            userRefund = excess - liquidationFee;

            // Transfer liquidation fee to admin (owner)
            if (liquidationFee > 0) {
                require(
                    usdc.transfer(owner(), liquidationFee),
                    "Fee transfer failed"
                );
            }

            // Transfer remaining USDC to user
            if (userRefund > 0) {
                require(
                    usdc.transfer(position.user, userRefund),
                    "Refund transfer failed"
                );
            }
        } else {
            liquidationFee = 0;
            userRefund = 0;
        }

        // Mark position as inactive
        position.active = false;
        position.collateralAmount = 0;

        emit LiquidationSettled(positionId, yieldReceived, debtRepaid, liquidationFee, userRefund);
    }

    /**
     * @notice Admin purchases liquidated Private Asset collateral and settles position
     * @param positionId Position ID
     * @param purchaseAmount USDC amount admin is paying (6 decimals)
     * @dev Admin sends USDC, receives Private Asset tokens, contract settles debt and fees
     *      Only for Private Asset collateral that has been liquidated
     */
    function purchaseAndSettleLiquidation(
        uint256 positionId,
        uint256 purchaseAmount
    ) external onlyOwner nonReentrant returns (uint256 liquidationFee, uint256 userRefund) {
        Position storage position = positions[positionId];
        require(position.active, "Position not active");
        require(positionsInLiquidation[positionId], "Position not liquidated");
        require(position.tokenType == TokenType.PRIVATE_ASSET, "Only for Private Assets");
        require(purchaseAmount > 0, "Purchase amount must be > 0");

        // Transfer USDC from admin
        require(
            usdc.transferFrom(msg.sender, address(this), purchaseAmount),
            "USDC transfer failed"
        );

        // Transfer Private Asset tokens to admin
        require(
            IERC20(position.collateralToken).transfer(msg.sender, position.collateralAmount),
            "Token transfer failed"
        );

        // Get outstanding debt
        uint256 outstandingDebt = ISeniorPool(seniorPool).getOutstandingDebt(positionId);

        uint256 debtRepaid = 0;

        if (outstandingDebt > 0) {
            // Repay as much debt as possible
            uint256 repaymentAmount = purchaseAmount > outstandingDebt
                ? outstandingDebt
                : purchaseAmount;

            usdc.approve(seniorPool, repaymentAmount);
            ISeniorPool(seniorPool).repay(positionId, repaymentAmount);
            debtRepaid = repaymentAmount;
        }

        // Calculate liquidation fee and user refund from excess
        if (purchaseAmount > debtRepaid) {
            uint256 excess = purchaseAmount - debtRepaid;

            // Calculate 10% liquidation fee
            liquidationFee = (excess * LIQUIDATION_FEE_BPS) / BASIS_POINTS;
            userRefund = excess - liquidationFee;

            // Transfer liquidation fee to admin (already msg.sender/owner)
            // Fee stays in contract, will be withdrawn by admin later
            // Or send to a separate fee collector address

            // Transfer remaining USDC to user
            if (userRefund > 0) {
                require(
                    usdc.transfer(position.user, userRefund),
                    "Refund transfer failed"
                );
            }
        } else {
            liquidationFee = 0;
            userRefund = 0;
        }

        // Mark position as inactive
        position.active = false;
        position.collateralAmount = 0;

        emit PrivateAssetLiquidationSettled(
            positionId,
            msg.sender,
            purchaseAmount,
            position.collateralAmount,
            debtRepaid,
            liquidationFee,
            userRefund
        );
    }

    /**
     * @notice Get health factor for position
     * @param positionId Position ID
     * @return Health factor (basis points, e.g., 15000 = 150%)
     */
    function getHealthFactor(uint256 positionId) public view returns (uint256) {
        Position memory position = positions[positionId];
        if (!position.active) return 0;

        uint256 outstandingDebt = ISeniorPool(seniorPool).getOutstandingDebt(positionId);
        if (outstandingDebt == 0) return type(uint256).max;

        // Health factor = (collateralValueUSD / debt) * BASIS_POINTS
        return (position.tokenValueUSD * BASIS_POINTS) / outstandingDebt;
    }

    /**
     * @notice Get position details
     * @param positionId Position ID
     * @return Position struct
     */
    function getPosition(uint256 positionId) external view returns (Position memory) {
        return positions[positionId];
    }

    /**
     * @notice Get max borrowable amount for position
     * @param positionId Position ID
     * @return Max USDC amount (6 decimals)
     */
    function getMaxBorrow(uint256 positionId) external view returns (uint256) {
        Position memory position = positions[positionId];
        if (!position.active) return 0;

        uint256 ltv = position.tokenType == TokenType.RWA ? RWA_LTV : PRIVATE_ASSET_LTV;
        uint256 maxBorrow = (position.tokenValueUSD * ltv) / BASIS_POINTS;
        uint256 currentDebt = ISeniorPool(seniorPool).getOutstandingDebt(positionId);

        return maxBorrow > currentDebt ? maxBorrow - currentDebt : 0;
    }

    /**
     * @notice Get repayment plan details
     * @param positionId Position ID
     * @return RepaymentPlan struct
     */
    function getRepaymentPlan(uint256 positionId) external view returns (RepaymentPlan memory) {
        return repaymentPlans[positionId];
    }
}

contracts/core/StARBLeverageVault.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

// SeniorPool interface
interface ISeniorPool {
    function borrow(uint256 positionId, uint256 amount) external;

    function repay(
        uint256 positionId,
        uint256 amount
    ) external returns (uint256 principal, uint256 interest);

    function getOutstandingDebt(uint256 positionId) external view returns (uint256);

    function getAccruedInterest(uint256 positionId) external view returns (uint256);
}

// ArbitrumSwapIntegration interface
interface IArbitrumSwapIntegration {
    function swapStARBToUSDC(uint256 stARBAmount, uint256 stARBPriceUSD) external returns (uint256);
}

// PrimaryMarket interface
interface IPrimaryMarket {
    function buyTokens(bytes32 assetId, uint256 amount) external;
}

/**
 * @title StARBLeverageVault
 * @notice Core vault for managing leveraged RWA token purchases using stARB collateral on Arbitrum
 * @dev Handles collateral custody, position management, yield harvesting, and settlement waterfall
 *
 * Flow:
 * 1. User deposits stARB as collateral (150% LTV)
 * 2. Vault borrows USDC from SeniorPool
 * 3. Backend purchases RWA tokens, transfers to vault
 * 4. Daily harvest: stARB yield → USDC → Interest payment
 * 5. Settlement: Waterfall distribution (Senior → Interest → User yield)
 * 6. Liquidation < 115%: Sell only buffer stARB (15%), return base 100% stARB to user
 * 7. RWA Settlement: Burn RWA tokens, repay loan, take 10% fee, refund user
 */
contract StARBLeverageVault is Ownable, ReentrancyGuard {
    // External contracts
    IERC20 public stARB;
    IERC20 public usdc;
    address public seniorPool;
    address public arbitrumSwapIntegration;
    address public yieldVault;
    address public primaryMarket;

    // Position tracking
    struct Position {
        address user; // Investor address
        uint256 stARBCollateral; // stARB deposited (18 decimals)
        uint256 usdcBorrowed; // USDC borrowed from SeniorPool (6 decimals)
        address rwaToken; // RWA token address
        uint256 rwaTokenAmount; // RWA tokens held (18 decimals)
        string assetId; // Asset ID reference
        uint256 createdAt; // Position creation timestamp
        uint256 lastHarvestTime; // Last yield harvest timestamp
        uint256 totalInterestPaid; // Cumulative interest paid
        uint256 liquidatedAt; // Liquidation timestamp (0 if not liquidated)
        bool active; // Position status
        bool inLiquidation; // Whether position is in liquidation process
    }

    mapping(uint256 => Position) public positions;
    uint256 public nextPositionId;

    // Health factor parameters
    uint256 public constant LIQUIDATION_THRESHOLD = 11500; // 115% (basis points)
    uint256 public constant INITIAL_LTV = 15000; // 150% (basis points)
    uint256 public constant LIQUIDATION_FEE_BPS = 1000; // 10% liquidation fee (basis points)
    uint256 public constant BASIS_POINTS = 10000;

    // Events
    event PositionCreated(
        uint256 indexed positionId,
        address indexed user,
        uint256 stARBCollateral,
        uint256 usdcBorrowed,
        address rwaToken,
        uint256 rwaTokenAmount
    );
    event YieldHarvested(
        uint256 indexed positionId,
        uint256 stARBSwapped,
        uint256 usdcReceived,
        uint256 interestPaid
    );
    event PositionLiquidated(
        uint256 indexed positionId,
        uint256 bufferStARBSold,
        uint256 usdcRecovered,
        uint256 baseStARBReturned,
        uint256 debtRepaid
    );
    event LiquidationSettled(
        uint256 indexed positionId,
        uint256 rwaTokensBurned,
        uint256 yieldReceived,
        uint256 debtRepaid,
        uint256 liquidationFee,
        uint256 userRefund
    );
    event SettlementProcessed(
        uint256 indexed positionId,
        uint256 seniorRepayment,
        uint256 interestRepayment,
        uint256 userYield
    );
    event CollateralAdded(uint256 indexed positionId, uint256 amount);

    /**
     * @notice Initialize StARB Leverage Vault
     * @param _stARB stARB token address
     * @param _usdc USDC token address
     * @param _seniorPool SeniorPool contract address
     * @param _arbitrumSwapIntegration ArbitrumSwapIntegration contract address
     * @dev stARB price is provided by backend in each function call (no on-chain oracle)
     */
    constructor(
        address _stARB,
        address _usdc,
        address _seniorPool,
        address _arbitrumSwapIntegration
    ) Ownable(msg.sender) {
        stARB = IERC20(_stARB);
        usdc = IERC20(_usdc);
        seniorPool = _seniorPool;
        arbitrumSwapIntegration = _arbitrumSwapIntegration;
        nextPositionId = 1;
    }

    /**
     * @notice Set YieldVault address (one-time)
     * @param _yieldVault YieldVault contract address
     */
    function setYieldVault(address _yieldVault) external onlyOwner {
        require(yieldVault == address(0), "YieldVault already set");
        require(_yieldVault != address(0), "Invalid address");
        yieldVault = _yieldVault;
    }

    /**
     * @notice Set PrimaryMarket address
     * @param _primaryMarket PrimaryMarket contract address
     */
    function setPrimaryMarket(address _primaryMarket) external onlyOwner {
        require(_primaryMarket != address(0), "Invalid address");
        primaryMarket = _primaryMarket;
    }

    /**
     * @notice Create leverage position
     * @param user Investor address
     * @param stARBAmount stARB collateral amount (18 decimals)
     * @param usdcToBorrow USDC to borrow (6 decimals)
     * @param rwaToken RWA token address
     * @param rwaTokenAmount RWA token amount (18 decimals)
     * @param assetId Asset ID reference (string)
     * @param assetIdBytes Asset ID reference (bytes32 for PrimaryMarket)
     * @param stARBPriceUSD Current stARB price in USD (18 decimals, e.g., 0.8e18 = $0.80)
     * @return positionId Created position ID
     */
    function createPosition(
        address user,
        uint256 stARBAmount,
        uint256 usdcToBorrow,
        address rwaToken,
        uint256 rwaTokenAmount,
        string memory assetId,
        bytes32 assetIdBytes,
        uint256 stARBPriceUSD
    ) external onlyOwner nonReentrant returns (uint256 positionId) {
        require(user != address(0), "Invalid user");
        require(stARBAmount > 0, "stARB amount must be > 0");
        require(usdcToBorrow > 0, "USDC amount must be > 0");
        require(rwaToken != address(0), "Invalid RWA token");
        require(stARBPriceUSD > 0, "Invalid stARB price");
        require(primaryMarket != address(0), "PrimaryMarket not set");

        // Verify LTV (collateral must be >= 150% of loan)
        // Calculate collateral value: (stARBAmount * stARBPriceUSD) / 1e30
        // 1e30 = 1e18 (stARB decimals) * 1e18 (price decimals) / 1e6 (USDC decimals)
        uint256 collateralValueUSD = (stARBAmount * stARBPriceUSD) / 1e30;
        uint256 requiredCollateral = (usdcToBorrow * INITIAL_LTV) / BASIS_POINTS;
        require(
            collateralValueUSD >= requiredCollateral,
            "Insufficient collateral (150% LTV required)"
        );

        // Transfer stARB from user to vault
        require(
            stARB.transferFrom(user, address(this), stARBAmount),
            "stARB transfer failed"
        );

        // Borrow USDC from SeniorPool
        ISeniorPool(seniorPool).borrow(nextPositionId, usdcToBorrow);

        // Buy RWA tokens from PrimaryMarket
        usdc.approve(primaryMarket, usdcToBorrow);
        IPrimaryMarket(primaryMarket).buyTokens(assetIdBytes, rwaTokenAmount);

        // Verify RWA tokens were received
        require(
            IERC20(rwaToken).balanceOf(address(this)) >= rwaTokenAmount, 
            "RWA token purchase failed"
        );

        // Create position
        positionId = nextPositionId++;
        positions[positionId] = Position({
            user: user,
            stARBCollateral: stARBAmount,
            usdcBorrowed: usdcToBorrow,
            rwaToken: rwaToken,
            rwaTokenAmount: rwaTokenAmount,
            assetId: assetId,
            createdAt: block.timestamp,
            lastHarvestTime: block.timestamp,
            totalInterestPaid: 0,
            liquidatedAt: 0,
            active: true,
            inLiquidation: false
        });

        emit PositionCreated(
            positionId,
            user,
            stARBAmount,
            usdcToBorrow,
            rwaToken,
            rwaTokenAmount
        );
    }

    /**
     * @notice Harvest stARB yield and pay interest
     * @param positionId Position ID
     * @param stARBPriceUSD Current stARB price in USD (18 decimals)
     * @return stARBSwapped Amount of stARB converted to USDC
     * @return usdcReceived Amount of USDC received from swap
     * @return interestPaid Amount of interest paid
     */
    function harvestYield(
        uint256 positionId,
        uint256 stARBPriceUSD
    )
        external
        onlyOwner
        nonReentrant
        returns (uint256 stARBSwapped, uint256 usdcReceived, uint256 interestPaid)
    {
        Position storage position = positions[positionId];
        require(position.active, "Position not active");
        require(stARBPriceUSD > 0, "Invalid stARB price");

        // Get outstanding interest from SeniorPool
        uint256 outstandingInterest = ISeniorPool(seniorPool).getAccruedInterest(
            positionId
        );
        require(outstandingInterest > 0, "No interest to pay");

        // Determine stARB to swap (enough to cover interest)
        stARBSwapped = _calculateStARBToSwap(outstandingInterest, stARBPriceUSD);
        require(stARBSwapped <= position.stARBCollateral, "Insufficient collateral");

        // Approve and swap stARB for USDC
        stARB.approve(arbitrumSwapIntegration, stARBSwapped);
        usdcReceived = IArbitrumSwapIntegration(arbitrumSwapIntegration).swapStARBToUSDC(
            stARBSwapped,
            stARBPriceUSD
        );

        // Pay interest to SeniorPool
        interestPaid = usdcReceived > outstandingInterest
            ? outstandingInterest
            : usdcReceived;
        usdc.approve(seniorPool, interestPaid);
        ISeniorPool(seniorPool).repay(positionId, interestPaid);

        // Update position
        position.stARBCollateral -= stARBSwapped;
        position.totalInterestPaid += interestPaid;
        position.lastHarvestTime = block.timestamp;

        emit YieldHarvested(positionId, stARBSwapped, usdcReceived, interestPaid);
    }

    /**
     * @notice Liquidate position if health factor < 115%
     * @dev Sells only buffer stARB (excess over 100% LTV), returns base stARB to user, holds RWA for settlement
     * @param positionId Position ID
     * @param stARBPriceUSD Current stARB price in USD (18 decimals)
     * @return bufferStARBSold Amount of excess stARB sold
     * @return usdcRecovered USDC from buffer sale
     * @return baseStARBReturned Base stARB collateral returned to user
     * @return debtRepaid Amount of debt repaid from buffer sale
     */
    function liquidatePosition(
        uint256 positionId,
        uint256 stARBPriceUSD
    ) external onlyOwner nonReentrant returns (uint256 bufferStARBSold, uint256 usdcRecovered, uint256 baseStARBReturned, uint256 debtRepaid) {
        Position storage position = positions[positionId];
        require(position.active, "Position not active");
        require(!position.inLiquidation, "Already in liquidation");
        require(stARBPriceUSD > 0, "Invalid stARB price");

        // Verify liquidation is necessary
        uint256 healthFactor = getHealthFactor(positionId, stARBPriceUSD);
        require(healthFactor < LIQUIDATION_THRESHOLD, "Position is healthy");

        address positionUser = position.user;
        uint256 outstandingDebt = ISeniorPool(seniorPool).getOutstandingDebt(positionId);

        // Calculate base collateral (100% of debt value in stARB)
        // baseStARB = (debt * 1e30) / stARBPrice
        uint256 baseStARBAmount = (outstandingDebt * 1e30) / stARBPriceUSD;

        // Calculate buffer (excess collateral = total - base)
        bufferStARBSold = position.stARBCollateral > baseStARBAmount 
            ? position.stARBCollateral - baseStARBAmount 
            : 0;

        require(bufferStARBSold > 0, "No buffer to sell");

        // Sell buffer stARB for USDC
        stARB.approve(arbitrumSwapIntegration, bufferStARBSold);
        usdcRecovered = IArbitrumSwapIntegration(arbitrumSwapIntegration).swapStARBToUSDC(
            bufferStARBSold,
            stARBPriceUSD
        );

        // Repay as much debt as possible with buffer proceeds
        debtRepaid = usdcRecovered > outstandingDebt ? outstandingDebt : usdcRecovered;
        if (debtRepaid > 0) {
            usdc.approve(seniorPool, debtRepaid);
            ISeniorPool(seniorPool).repay(positionId, debtRepaid);
        }

        // Return base stARB collateral to user
        baseStARBReturned = baseStARBAmount;
        if (baseStARBReturned > 0) {
            require(
                stARB.transfer(positionUser, baseStARBReturned),
                "Base stARB transfer failed"
            );
        }

        // Update position - keep active to hold RWA tokens until settlement
        position.stARBCollateral = 0; // All stARB distributed (buffer sold, base returned)
        position.inLiquidation = true;
        position.liquidatedAt = block.timestamp;

        emit PositionLiquidated(positionId, bufferStARBSold, usdcRecovered, baseStARBReturned, debtRepaid);
    }

    /**
     * @notice Claim USDC yield by burning RWA tokens held by this vault
     * @param positionId Position ID
     * @param _yieldVault YieldVault contract address
     * @param rwaToken RWA token address
     * @param tokenAmount Amount of RWA tokens to burn
     * @return usdcReceived Amount of USDC received from YieldVault
     */
    function claimYieldFromBurn(
        uint256 positionId,
        address _yieldVault,
        address rwaToken,
        uint256 tokenAmount
    ) external onlyOwner nonReentrant returns (uint256 usdcReceived) {
        Position storage position = positions[positionId];
        require(position.active, "Position not active");
        require(position.rwaToken == rwaToken, "Token mismatch");
        require(tokenAmount <= position.rwaTokenAmount, "Insufficient RWA tokens");

        // Approve YieldVault to burn tokens from this contract
        IERC20(rwaToken).approve(_yieldVault, tokenAmount);

        // Get USDC balance before claim
        uint256 balanceBefore = usdc.balanceOf(address(this));

        // Call YieldVault.claimYield to burn tokens and receive USDC
        (bool success, ) = _yieldVault.call(
            abi.encodeWithSignature("claimYield(address,uint256)", rwaToken, tokenAmount)
        );
        require(success, "YieldVault claim failed");

        // Calculate USDC received
        uint256 balanceAfter = usdc.balanceOf(address(this));
        usdcReceived = balanceAfter - balanceBefore;

        // Update position
        position.rwaTokenAmount -= tokenAmount;

        return usdcReceived;
    }

    /**
     * @notice Settle liquidated position by burning RWA tokens for yield
     * @dev Called after RWA settlement - burns RWA, repays remaining debt, takes 10% fee, refunds user
     * @param positionId Position ID
     * @return yieldReceived USDC received from burning RWA tokens
     * @return liquidationFee 10% liquidation fee sent to admin
     * @return userRefund Remaining USDC sent to user
     */
    function settleLiquidation(
        uint256 positionId
    ) external onlyOwner nonReentrant returns (uint256 yieldReceived, uint256 liquidationFee, uint256 userRefund) {
        Position storage position = positions[positionId];
        require(position.active, "Position not active");
        require(position.inLiquidation, "Position not in liquidation");
        require(yieldVault != address(0), "YieldVault not set");
        require(position.rwaTokenAmount > 0, "No RWA tokens to burn");

        // Approve YieldVault to burn RWA tokens
        IERC20(position.rwaToken).approve(yieldVault, position.rwaTokenAmount);

        // Get USDC balance before
        uint256 balanceBefore = usdc.balanceOf(address(this));

        // Burn RWA tokens to claim USDC yield
        (bool success, ) = yieldVault.call(
            abi.encodeWithSignature("claimYield(address,uint256)", position.rwaToken, position.rwaTokenAmount)
        );
        require(success, "YieldVault claim failed");

        // Calculate USDC received
        uint256 balanceAfter = usdc.balanceOf(address(this));
        yieldReceived = balanceAfter - balanceBefore;
        require(yieldReceived > 0, "No yield received");

        uint256 rwaTokensBurned = position.rwaTokenAmount;
        position.rwaTokenAmount = 0;

        // Get outstanding debt
        uint256 outstandingDebt = ISeniorPool(seniorPool).getOutstandingDebt(positionId);
        uint256 debtRepaid = 0;

        if (outstandingDebt > 0) {
            // Repay as much debt as possible
            uint256 repaymentAmount = yieldReceived > outstandingDebt ? outstandingDebt : yieldReceived;
            usdc.approve(seniorPool, repaymentAmount);
            ISeniorPool(seniorPool).repay(positionId, repaymentAmount);
            debtRepaid = repaymentAmount;
        }

        // Calculate liquidation fee and user refund from excess
        if (yieldReceived > debtRepaid) {
            uint256 excess = yieldReceived - debtRepaid;

            // Calculate 10% liquidation fee
            liquidationFee = (excess * LIQUIDATION_FEE_BPS) / BASIS_POINTS;
            userRefund = excess - liquidationFee;

            // Transfer liquidation fee to admin (owner)
            if (liquidationFee > 0) {
                require(
                    usdc.transfer(owner(), liquidationFee),
                    "Fee transfer failed"
                );
            }

            // Transfer remaining USDC to user
            if (userRefund > 0) {
                require(
                    usdc.transfer(position.user, userRefund),
                    "Refund transfer failed"
                );
            }
        } else {
            liquidationFee = 0;
            userRefund = 0;
        }

        // Mark position as inactive
        position.active = false;

        emit LiquidationSettled(positionId, rwaTokensBurned, yieldReceived, debtRepaid, liquidationFee, userRefund);
    }

    /**
     * @notice Process settlement waterfall when RWA asset settles
     * @param positionId Position ID
     * @param settlementUSDC Total USDC from asset settlement
     * @return seniorRepayment Amount repaid to SeniorPool
     * @return interestRepayment Amount paid for interest
     * @return userYield Amount distributed to user
     */
    function processSettlement(
        uint256 positionId,
        uint256 settlementUSDC
    )
        external
        onlyOwner
        nonReentrant
        returns (uint256 seniorRepayment, uint256 interestRepayment, uint256 userYield)
    {
        Position storage position = positions[positionId];
        require(position.active, "Position not active");

        // Get outstanding debt from SeniorPool
        uint256 totalDebt = ISeniorPool(seniorPool).getOutstandingDebt(positionId);

        // Waterfall distribution:
        // 1. Senior Pool principal
        // 2. Accrued interest
        // 3. Remaining USDC to user
        if (settlementUSDC >= totalDebt) {
            // Full repayment + user yield
            usdc.approve(seniorPool, totalDebt);
            (seniorRepayment, interestRepayment) = ISeniorPool(seniorPool).repay(
                positionId,
                totalDebt
            );
            userYield = settlementUSDC - totalDebt;

            // Transfer user yield
            if (userYield > 0) {
                require(
                    usdc.transfer(position.user, userYield),
                    "User yield transfer failed"
                );
            }
        } else {
            // Partial repayment (prioritize principal, then interest)
            usdc.approve(seniorPool, settlementUSDC);
            (seniorRepayment, interestRepayment) = ISeniorPool(seniorPool).repay(
                positionId,
                settlementUSDC
            );
            userYield = 0;
        }

        // Return remaining stARB collateral to user
        if (position.stARBCollateral > 0) {
            require(
                stARB.transfer(position.user, position.stARBCollateral),
                "stARB return failed"
            );
        }

        // Mark position as inactive
        position.active = false;

        emit SettlementProcessed(
            positionId,
            seniorRepayment,
            interestRepayment,
            userYield
        );
    }

    /**
     * @notice Add collateral to position
     * @param positionId Position ID
     * @param stARBAmount Additional stARB collateral
     */
    function addCollateral(
        uint256 positionId,
        uint256 stARBAmount
    ) external nonReentrant {
        Position storage position = positions[positionId];
        require(position.active, "Position not active");
        require(msg.sender == position.user, "Not position owner");
        require(stARBAmount > 0, "Amount must be > 0");

        // Transfer stARB from user
        require(
            stARB.transferFrom(msg.sender, address(this), stARBAmount),
            "stARB transfer failed"
        );

        position.stARBCollateral += stARBAmount;

        emit CollateralAdded(positionId, stARBAmount);
    }

    /**
     * @notice Get health factor for position
     * @param positionId Position ID
     * @param stARBPriceUSD Current stARB price in USD (18 decimals)
     * @return Health factor (basis points, e.g., 15000 = 150%)
     */
    function getHealthFactor(uint256 positionId, uint256 stARBPriceUSD) public view returns (uint256) {
        Position memory position = positions[positionId];
        if (!position.active) return 0;
        require(stARBPriceUSD > 0, "Invalid stARB price");

        // Calculate collateral value: (stARBAmount * stARBPriceUSD) / 1e30
        uint256 collateralValueUSD = (position.stARBCollateral * stARBPriceUSD) / 1e30;
        uint256 outstandingDebt = ISeniorPool(seniorPool).getOutstandingDebt(
            positionId
        );

        if (outstandingDebt == 0) return type(uint256).max;

        // Health factor = (collateralValue / debt) * BASIS_POINTS
        return (collateralValueUSD * BASIS_POINTS) / outstandingDebt;
    }

    /**
     * @notice Get position details
     * @param positionId Position ID
     * @return Position struct
     */
    function getPosition(uint256 positionId) external view returns (Position memory) {
        return positions[positionId];
    }

    /**
     * @notice Calculate stARB to swap for target USDC amount
     * @param targetUSDC Target USDC amount (6 decimals)
     * @param stARBPrice Current stARB price (18 decimals)
     * @return stARB amount needed (18 decimals)
     */
    function _calculateStARBToSwap(
        uint256 targetUSDC,
        uint256 stARBPrice
    ) internal pure returns (uint256) {
        // stARB = (targetUSDC * 1e18 * 1e12) / stARBPrice
        // 1e12 converts USDC (6 decimals) to 18 decimals
        return (targetUSDC * 1e30) / stARBPrice;
    }
}

contracts/core/TokenFactory.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "./RWAToken.sol";
import "./PrivateAssetToken.sol";
import "./ComplianceModule.sol";
import "./YieldVault.sol";
import "./AttestationRegistry.sol";

contract TokenFactory {
    struct TokenSuite {
        address token;
        address compliance;
        uint256 deployedAt;
        uint256 totalSupply;
    }

    address public attestationRegistry;
    address public identityRegistry;
    address public trustedIssuersRegistry;
    address public platformCustody;
    address public yieldVault;
    address public owner;

    mapping(bytes32 => TokenSuite) public deployedTokens;
    address[] public allTokens;
    uint256 public tokenCount;

    event TokenSuiteDeployed(bytes32 indexed assetId, address token, address compliance, uint256 totalSupply);
    event PrivateAssetTokenDeployed(
        bytes32 indexed assetId,
        address token,
        address compliance,
        uint256 totalSupply,
        string assetType,
        uint256 valuation
    );

    modifier onlyOwner() {
        require(msg.sender == owner, "Only owner");
        _;
    }

    constructor(
        address _attestationRegistry,
        address _identityRegistry,
        address _trustedIssuersRegistry,
        address _platformCustody,
        address _yieldVault
    ) {
        owner = msg.sender;
        attestationRegistry = _attestationRegistry;
        identityRegistry = _identityRegistry;
        trustedIssuersRegistry = _trustedIssuersRegistry;
        platformCustody = _platformCustody;
        yieldVault = _yieldVault;
    }

    function deployTokenSuite(
        bytes32 assetId,
        uint256 totalSupply,
        string memory name,
        string memory symbol,
        address issuer
    ) external onlyOwner {
        require(deployedTokens[assetId].token == address(0), "Asset already tokenized");
        require(AttestationRegistry(attestationRegistry).isAssetValid(assetId), "Asset not valid");

        // 1. Deploy Compliance
        ComplianceModule compliance = new ComplianceModule(
            identityRegistry,
            attestationRegistry,
            assetId
        );

        // 2. Deploy Token
        RWAToken token = new RWAToken(
            assetId,
            address(compliance),
            identityRegistry,
            totalSupply,
            platformCustody,
            name,
            symbol,
            issuer
        );

        // 3. Link Compliance (RWAToken already sets compliance, but if Compliance needed token ref, do it here)
        // In this design, Compliance checks Registry directly, doesn't need token callback usually.

        // 4. Register in YieldVault
        YieldVault(yieldVault).registerAsset(address(token), assetId, issuer);

        // 5. Store Suite
        deployedTokens[assetId] = TokenSuite({
            token: address(token),
            compliance: address(compliance),
            deployedAt: block.timestamp,
            totalSupply: totalSupply
        });

        allTokens.push(address(token));
        tokenCount++;

        emit TokenSuiteDeployed(assetId, address(token), address(compliance), totalSupply);
    }

    /**
     * @notice Deploy PrivateAssetToken suite with metadata
     * @param assetId Unique asset identifier
     * @param totalSupply Total token supply (usually 1e18 for whole asset)
     * @param name Token name
     * @param symbol Token symbol
     * @param issuer Issuer address
     * @param assetType Asset type ("DEED", "BOND", "INVOICE", etc.)
     * @param location Physical location
     * @param valuation Initial USD valuation (6 decimals)
     * @param documentHash IPFS hash for documents
     */
    function deployPrivateAssetTokenSuite(
        bytes32 assetId,
        uint256 totalSupply,
        string memory name,
        string memory symbol,
        address issuer,
        string memory assetType,
        string memory location,
        uint256 valuation,
        string memory documentHash
    ) external onlyOwner {
        require(deployedTokens[assetId].token == address(0), "Asset already tokenized");
        require(valuation > 0, "Valuation must be > 0");

        // 1. Deploy Compliance
        ComplianceModule compliance = new ComplianceModule(
            identityRegistry,
            attestationRegistry,
            assetId
        );

        // 2. Deploy PrivateAssetToken
        PrivateAssetToken token = new PrivateAssetToken(
            assetId,
            address(compliance),
            identityRegistry,
            totalSupply,
            platformCustody,
            name,
            symbol,
            issuer,
            assetType,
            location,
            valuation,
            documentHash
        );

        // 3. Register in YieldVault (same as RWA tokens)
        YieldVault(yieldVault).registerAsset(address(token), assetId, issuer);

        // 4. Store Suite
        deployedTokens[assetId] = TokenSuite({
            token: address(token),
            compliance: address(compliance),
            deployedAt: block.timestamp,
            totalSupply: totalSupply
        });

        allTokens.push(address(token));
        tokenCount++;

        emit PrivateAssetTokenDeployed(
            assetId,
            address(token),
            address(compliance),
            totalSupply,
            assetType,
            valuation
        );
    }

    function getTokenByAssetId(bytes32 assetId) external view returns (TokenSuite memory) {
        return deployedTokens[assetId];
    }

    function getAllTokens() external view returns (address[] memory) {
        return allTokens;
    }
}

contracts/core/TrustedIssuersRegistry.so.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

contract TrustedIssuersRegistry {
    mapping(address => bool) public trustedIssuers;
    address public owner;

    event TrustedIssuerAdded(address indexed issuer, uint256 timestamp);
    event TrustedIssuerRemoved(address indexed issuer, uint256 timestamp);

    modifier onlyOwner() {
        require(msg.sender == owner, "Only owner");
        _;
    }

    constructor() {
        owner = msg.sender;
    }

    function addTrustedIssuer(address issuer) external onlyOwner {
        trustedIssuers[issuer] = true;
        emit TrustedIssuerAdded(issuer, block.timestamp);
    }

    function removeTrustedIssuer(address issuer) external onlyOwner {
        trustedIssuers[issuer] = false;
        emit TrustedIssuerRemoved(issuer, block.timestamp);
    }

    function isTrustedIssuer(address issuer) external view returns (bool) {
        return trustedIssuers[issuer];
    }
}

contracts/core/YieldVault.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";

interface IBurnableToken {
    function burn(uint256 amount) external;
    function burnFrom(address account, uint256 amount) external;
    function totalSupply() external view returns (uint256);
}

contract YieldVault {
    struct AssetYield {
        address tokenAddress;
        bytes32 assetId;
        address issuer;
        uint256 totalSettlement;      // Total USDC deposited for settlement (after platform fee)
        uint256 totalTokenSupply;     // Total RWA token supply at settlement time
        uint256 totalClaimed;         // Total USDC claimed by investors
        uint256 totalTokensBurned;    // Total RWA tokens burned during claims
        uint256 settlementTimestamp;  // When settlement was deposited
        bool isSettled;               // Whether settlement has been deposited
    }

    struct UserYield {
        uint256 totalClaimable;       // DEPRECATED - kept for backwards compatibility
        uint256 lastClaimTime;
    }

    IERC20 public USDC;
    address public platform;
    address public factory;

    mapping(address => AssetYield) public assets;
    mapping(address => UserYield) public userYields;
    address[] public registeredAssets;

    event AssetRegistered(address indexed tokenAddress, bytes32 indexed assetId, address issuer);
    event SettlementDeposited(address indexed tokenAddress, bytes32 indexed assetId, uint256 totalSettlement, uint256 totalTokenSupply, uint256 timestamp);
    event YieldClaimed(address indexed user, address indexed tokenAddress, uint256 tokensBurned, uint256 usdcReceived, uint256 timestamp);

    // DEPRECATED EVENTS - kept for backwards compatibility
    event YieldDeposited(address indexed tokenAddress, bytes32 indexed assetId, uint256 amount, uint256 timestamp);
    event YieldDistributed(address indexed tokenAddress, uint256 totalAmount, uint256 holderCount, uint256 timestamp);

    modifier onlyPlatform() {
        require(msg.sender == platform, "Only platform");
        _;
    }

    modifier onlyFactory() {
        require(msg.sender == factory, "Only factory");
        _;
    }

    constructor(address _USDC, address _platform) {
        USDC = IERC20(_USDC);
        platform = _platform;
    }

    function setFactory(address _factory) external {
        require(factory == address(0), "Factory already set");
        factory = _factory;
    }

    function registerAsset(address tokenAddress, bytes32 assetId, address issuer) external onlyFactory {
        assets[tokenAddress].tokenAddress = tokenAddress;
        assets[tokenAddress].assetId = assetId;
        assets[tokenAddress].issuer = issuer;
        registeredAssets.push(tokenAddress);
        emit AssetRegistered(tokenAddress, assetId, issuer);
    }

    /**
     * @notice Deposit settlement USDC for an asset (new burn-to-claim model)
     * @param tokenAddress The RWA token address
     * @param totalSettlement The total USDC to distribute (after platform fee)
     */
    function depositSettlement(address tokenAddress, uint256 totalSettlement) external onlyPlatform {
        require(assets[tokenAddress].tokenAddress != address(0), "Asset not registered");
        require(!assets[tokenAddress].isSettled, "Settlement already deposited");
        require(totalSettlement > 0, "Settlement must be > 0");

        // Get total token supply at settlement time
        uint256 totalTokenSupply = IBurnableToken(tokenAddress).totalSupply();
        require(totalTokenSupply > 0, "Token supply is zero");

        // Transfer USDC from platform to vault
        require(USDC.transferFrom(msg.sender, address(this), totalSettlement), "USDC transfer failed");

        // Record settlement
        assets[tokenAddress].totalSettlement = totalSettlement;
        assets[tokenAddress].totalTokenSupply = totalTokenSupply;
        assets[tokenAddress].settlementTimestamp = block.timestamp;
        assets[tokenAddress].isSettled = true;

        emit SettlementDeposited(tokenAddress, assets[tokenAddress].assetId, totalSettlement, totalTokenSupply, block.timestamp);
    }

    /**
     * @notice DEPRECATED: Old yield deposit function (kept for backwards compatibility)
     */
    function depositYield(address tokenAddress, uint256 amount) external onlyPlatform {
        require(assets[tokenAddress].tokenAddress != address(0), "Asset not registered");
        require(amount > 0, "Amount must be > 0");

        require(USDC.transferFrom(msg.sender, address(this), amount), "Transfer failed");

        // For backwards compatibility, treat as settlement if not yet settled
        if (!assets[tokenAddress].isSettled) {
            uint256 totalTokenSupply = IBurnableToken(tokenAddress).totalSupply();
            assets[tokenAddress].totalSettlement = amount;
            assets[tokenAddress].totalTokenSupply = totalTokenSupply;
            assets[tokenAddress].settlementTimestamp = block.timestamp;
            assets[tokenAddress].isSettled = true;
        }

        emit YieldDeposited(tokenAddress, assets[tokenAddress].assetId, amount, block.timestamp);
    }

    /**
     * @notice DEPRECATED: Old batch distribution function (kept for backwards compatibility)
     */
    function distributeYieldBatch(
        address tokenAddress,
        address[] calldata holders,
        uint256[] calldata amounts
    ) external onlyPlatform {
        require(holders.length == amounts.length, "Array mismatch");
        uint256 totalAmount = 0;

        for (uint256 i = 0; i < amounts.length; i++) {
            totalAmount += amounts[i];
            userYields[holders[i]].totalClaimable += amounts[i];
        }

        // Note: Old accounting fields removed in new model
        // This function is kept only for emergency backwards compatibility
        emit YieldDistributed(tokenAddress, totalAmount, holders.length, block.timestamp);
    }

    /**
     * @notice Claim yield by burning RWA tokens (new burn-to-claim model)
     * @param tokenAddress The RWA token address
     * @param tokenAmount The amount of RWA tokens to burn and claim yield for
     */
    function claimYield(address tokenAddress, uint256 tokenAmount) external {
        require(assets[tokenAddress].isSettled, "Settlement not deposited yet");
        require(tokenAmount > 0, "Token amount must be > 0");

        AssetYield storage asset = assets[tokenAddress];

        // Calculate USDC to send: (tokenAmount / totalTokenSupply) * totalSettlement
        uint256 usdcAmount = (tokenAmount * asset.totalSettlement) / asset.totalTokenSupply;
        require(usdcAmount > 0, "USDC amount too small");

        // Ensure vault has enough USDC
        uint256 remainingSettlement = asset.totalSettlement - asset.totalClaimed;
        require(usdcAmount <= remainingSettlement, "Insufficient USDC in vault");

        // Burn investor's RWA tokens
        IBurnableToken(tokenAddress).burnFrom(msg.sender, tokenAmount);

        // Update accounting
        asset.totalClaimed += usdcAmount;
        asset.totalTokensBurned += tokenAmount;
        userYields[msg.sender].lastClaimTime = block.timestamp;

        // Transfer USDC to investor
        require(USDC.transfer(msg.sender, usdcAmount), "USDC transfer failed");

        emit YieldClaimed(msg.sender, tokenAddress, tokenAmount, usdcAmount, block.timestamp);
    }

    /**
     * @notice DEPRECATED: Old claim function (kept for backwards compatibility)
     */
    function claimAllYield() external {
        uint256 claimable = userYields[msg.sender].totalClaimable;
        require(claimable > 0, "Nothing to claim");

        userYields[msg.sender].totalClaimable = 0;
        userYields[msg.sender].lastClaimTime = block.timestamp;

        require(USDC.transfer(msg.sender, claimable), "Transfer failed");

        // Note: Cannot emit new YieldClaimed event format without tokenAddress
        // Keep old behavior for backwards compatibility
    }

    /**
     * @notice Get claimable USDC for a token amount (new model)
     * @param tokenAddress The RWA token address
     * @param tokenAmount The amount of tokens to check
     * @return The USDC amount claimable for the given token amount
     */
    function getClaimableForTokens(address tokenAddress, uint256 tokenAmount) external view returns (uint256) {
        if (!assets[tokenAddress].isSettled || tokenAmount == 0) {
            return 0;
        }

        return (tokenAmount * assets[tokenAddress].totalSettlement) / assets[tokenAddress].totalTokenSupply;
    }

    /**
     * @notice Get settlement info for an asset
     * @param tokenAddress The RWA token address
     * @return totalSettlement Total USDC deposited
     * @return totalTokenSupply Total RWA token supply at settlement
     * @return totalClaimed Total USDC claimed so far
     * @return totalTokensBurned Total tokens burned so far
     * @return yieldPerToken USDC yield per token (in 6 decimals)
     */
    function getSettlementInfo(address tokenAddress) external view returns (
        uint256 totalSettlement,
        uint256 totalTokenSupply,
        uint256 totalClaimed,
        uint256 totalTokensBurned,
        uint256 yieldPerToken
    ) {
        AssetYield storage asset = assets[tokenAddress];
        totalSettlement = asset.totalSettlement;
        totalTokenSupply = asset.totalTokenSupply;
        totalClaimed = asset.totalClaimed;
        totalTokensBurned = asset.totalTokensBurned;
        yieldPerToken = totalTokenSupply > 0 ? (totalSettlement * 1e18) / totalTokenSupply : 0;
    }

    /**
     * @notice DEPRECATED: Old getUserClaimable (kept for backwards compatibility)
     */
    function getUserClaimable(address user) external view returns (uint256) {
        return userYields[user].totalClaimable;
    }
}

contracts/integrations/ArbitrumSwapInteg.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

// DEX interface
interface IArbitrumDEX {
    function swapStARBForUSDC(
        uint256 stARBAmount,
        uint256 minUSDCOut
    ) external returns (uint256 usdcOut);

    function getQuote(uint256 stARBAmount) external view returns (uint256);
}

// Price oracle interface
interface IStARBPriceOracle {
    function getPrice() external view returns (uint256);
}

/**
 * @title ArbitrumSwapIntegration
 * @notice Wrapper for Arbitrum DEX integration with slippage protection
 * @dev Handles stARB → USDC swaps for yield harvesting with safety checks
 *
 * Features:
 * - Slippage protection (max 3%)
 * - Price validation against oracle
 * - Swap statistics tracking
 * - Emergency pause functionality
 */
contract ArbitrumSwapIntegration is Ownable, ReentrancyGuard {

    IERC20 public stARB;
    IERC20 public usdc;
    IArbitrumDEX public dex;
    IStARBPriceOracle public priceOracle;

    // Slippage parameters
    uint256 public constant MAX_SLIPPAGE = 300; // 3% max slippage (basis points)
    uint256 public constant BASIS_POINTS = 10000;

    // Swap statistics
    uint256 public totalSwapsExecuted;
    uint256 public totalStARBSwapped;
    uint256 public totalUSDCReceived;

    // Emergency controls
    bool public paused;

    // Events
    event SwapExecuted(
        uint256 indexed timestamp,
        uint256 stARBAmount,
        uint256 usdcReceived,
        uint256 effectiveRate
    );
    event SlippageExceeded(uint256 expected, uint256 actual, uint256 slippage);
    event PausedUpdated(bool paused);

    modifier whenNotPaused() {
        require(!paused, "Contract is paused");
        _;
    }

    /**
     * @notice Initialize Arbitrum Swap Integration
     * @param _stARB stARB token address
     * @param _usdc USDC token address
     * @param _dex Arbitrum DEX address
     * @param _priceOracle Price oracle address (can be stARB token itself)
     */
    constructor(
        address _stARB,
        address _usdc,
        address _dex,
        address _priceOracle
    ) Ownable(msg.sender) {
        stARB = IERC20(_stARB);
        usdc = IERC20(_usdc);
        dex = IArbitrumDEX(_dex);
        priceOracle = IStARBPriceOracle(_priceOracle);
        paused = false;
    }

    /**
     * @notice Pause/unpause swaps (emergency)
     * @param _paused New pause state
     */
    function setPaused(bool _paused) external onlyOwner {
        paused = _paused;
        emit PausedUpdated(_paused);
    }

    /**
     * @notice Update DEX address
     * @param _dex New DEX address
     */
    function setDEX(address _dex) external onlyOwner {
        require(_dex != address(0), "Invalid address");
        dex = IArbitrumDEX(_dex);
    }

    /**
     * @notice Update price oracle address
     * @param _oracle New oracle address
     */
    function setPriceOracle(address _oracle) external onlyOwner {
        require(_oracle != address(0), "Invalid address");
        priceOracle = IStARBPriceOracle(_oracle);
    }

    /**
     * @notice Swap stARB for USDC with slippage protection
     * @param stARBAmount Amount of stARB to swap (18 decimals)
     * @param stARBPriceUSD Current stARB price in USD (18 decimals, provided by backend)
     * @return usdcReceived Amount of USDC received (6 decimals)
     */
    function swapStARBToUSDC(
        uint256 stARBAmount,
        uint256 stARBPriceUSD
    ) external nonReentrant whenNotPaused returns (uint256 usdcReceived) {
        require(stARBAmount > 0, "Amount must be > 0");
        require(stARBPriceUSD > 0, "Invalid stARB price");

        // Get quote from DEX
        uint256 expectedUSDC = dex.getQuote(stARBAmount);
        require(expectedUSDC > 0, "Invalid quote");

        // Validate quote against provided price
        // _validatePrice(stARBAmount, expectedUSDC, stARBPriceUSD);

        // Calculate minimum output with slippage tolerance
        uint256 minUSDCOut = (expectedUSDC * (BASIS_POINTS - MAX_SLIPPAGE)) /
            BASIS_POINTS;

        // Transfer stARB from caller to this contract
        require(
            stARB.transferFrom(msg.sender, address(this), stARBAmount),
            "stARB transfer failed"
        );

        // Approve DEX to spend stARB
        stARB.approve(address(dex), stARBAmount);

        // Execute swap
        usdcReceived = dex.swapStARBForUSDC(stARBAmount, minUSDCOut);

        // Verify slippage is within tolerance
        uint256 slippageBps = ((expectedUSDC - usdcReceived) * BASIS_POINTS) /
            expectedUSDC;
        require(slippageBps <= MAX_SLIPPAGE, "Slippage exceeded");

        // Update statistics
        totalSwapsExecuted++;
        totalStARBSwapped += stARBAmount;
        totalUSDCReceived += usdcReceived;

        // Transfer USDC to caller
        require(usdc.transfer(msg.sender, usdcReceived), "USDC transfer failed");

        // Calculate effective rate (USDC per stARB, 6 decimals)
        uint256 effectiveRate = (usdcReceived * 1e18) / stARBAmount;

        emit SwapExecuted(block.timestamp, stARBAmount, usdcReceived, effectiveRate);
    }

    /**
     * @notice Get swap quote from DEX
     * @param stARBAmount Amount of stARB (18 decimals)
     * @return Expected USDC output (6 decimals)
     */
    function getQuote(uint256 stARBAmount) external view returns (uint256) {
        return dex.getQuote(stARBAmount);
    }

    /**
     * @notice Get stARB price from oracle
     * @return Price in USD (18 decimals)
     */
    function getStARBPrice() external view returns (uint256) {
        return priceOracle.getPrice();
    }

    /**
     * @notice Calculate USD value of stARB amount
     * @param stARBAmount Amount of stARB (18 decimals)
     * @return USD value (6 decimals for USDC)
     */
    function getStARBValueUSD(uint256 stARBAmount) external view returns (uint256) {
        uint256 priceUSD = priceOracle.getPrice(); // 18 decimals
        // Convert to USDC 6 decimals: (stARB * price) / 1e18 / 1e12
        return (stARBAmount * priceUSD) / 1e30;
    }

    /**
     * @notice Get swap statistics
     * @return Total swaps, total stARB swapped, total USDC received
     */
    function getSwapStats() external view returns (uint256, uint256, uint256) {
        return (totalSwapsExecuted, totalStARBSwapped, totalUSDCReceived);
    }

    /**
     * @notice Validate swap price against provided stARB price
     * @param stARBAmount stARB amount being swapped
     * @param expectedUSDC Expected USDC from DEX quote
     * @param stARBPriceUSD stARB price provided by backend (18 decimals)
     */
    function _validatePrice(uint256 stARBAmount, uint256 expectedUSDC, uint256 stARBPriceUSD) internal pure {
        // Calculate expected USDC from provided price
        uint256 priceExpectedUSDC = (stARBAmount * stARBPriceUSD) / 1e30; // Convert to 6 decimals

        // Allow 5% deviation between provided price and DEX
        uint256 maxDeviation = 10000; // 100% in basis points
        uint256 deviationBps;

        if (expectedUSDC > priceExpectedUSDC) {
            deviationBps =
                ((expectedUSDC - priceExpectedUSDC) * BASIS_POINTS) /
                priceExpectedUSDC;
        } else {
            deviationBps =
                ((priceExpectedUSDC - expectedUSDC) * BASIS_POINTS) /
                priceExpectedUSDC;
        }

        require(
            deviationBps <= maxDeviation,
            "Price deviation too high"
        );
    }

    /**
     * @notice Emergency withdraw tokens (owner only)
     * @param token Token address
     * @param amount Amount to withdraw
     */
    function emergencyWithdraw(
        address token,
        uint256 amount
    ) external onlyOwner {
        require(IERC20(token).transfer(owner(), amount), "Transfer failed");
    }
}

contracts/integrations/OAID.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

/**
 * @title OAID (On-chain Asset ID)
 * @notice Issues credit lines backed by private asset tokens locked in SolvencyVault
 * @dev External protocols can verify credit lines and extend credit based on collateral
 *
 * Flow:
 * 1. User completes KYC → registerUser() creates OAID profile
 * 2. User deposits collateral → SolvencyVault calls issueCreditLine()
 * 3. External protocols query credit availability
 * 4. When SolvencyVault position is liquidated, credit line is revoked
 */
contract OAID is Ownable, ReentrancyGuard {
    // Payment history entry
    struct PaymentRecord {
        uint256 timestamp;          // Payment time
        uint256 amount;             // Amount paid (6 decimals)
        bool onTime;                // Whether payment was on time
        uint256 daysLate;           // Days late (0 if on time)
    }

    // Credit line structure
    struct CreditLine {
        address user;                   // Borrower address
        address collateralToken;        // Token backing the credit
        uint256 collateralAmount;       // Token amount (18 decimals)
        uint256 creditLimit;            // Max credit in USD (6 decimals)
        uint256 creditUsed;             // Credit utilized externally (6 decimals)
        uint256 solvencyPositionId;     // Reference to SolvencyVault position
        uint256 issuedAt;               // Creation timestamp
        uint256 totalPayments;          // Total number of payments made
        uint256 onTimePayments;         // Number of on-time payments
        uint256 latePayments;           // Number of late payments
        uint256 totalAmountRepaid;      // Total amount repaid (6 decimals)
        bool liquidated;                // Whether position was liquidated
        uint256 liquidatedAt;           // Liquidation timestamp (0 if not liquidated)
        bool active;                    // Credit line status
    }

    // Authorized vaults
    address public solvencyVault;

    // User registration
    mapping(address => bool) public registeredUsers;
    mapping(address => uint256) public userRegistrationTime;

    // Credit line management
    mapping(uint256 => CreditLine) public creditLines;
    uint256 public nextCreditLineId;

    // Payment history
    mapping(uint256 => PaymentRecord[]) public paymentHistory; // creditLineId => payments

    // User credit lines
    mapping(address => uint256[]) public userCreditLines;

    // Events
    event UserRegistered(
        address indexed user,
        uint256 timestamp
    );
    event CreditLineIssued(
        uint256 indexed creditLineId,
        address indexed user,
        address collateralToken,
        uint256 collateralAmount,
        uint256 creditLimit,
        uint256 solvencyPositionId
    );
    event CreditLineUpdated(
        uint256 indexed creditLineId,
        uint256 oldCreditLimit,
        uint256 newCreditLimit
    );
    event CreditUsed(
        uint256 indexed creditLineId,
        uint256 amount,
        uint256 totalUsed
    );
    event CreditRepaid(
        uint256 indexed creditLineId,
        uint256 amount,
        uint256 remainingUsed
    );
    event CreditLineRevoked(
        uint256 indexed creditLineId,
        string reason
    );
    event PaymentRecorded(
        uint256 indexed creditLineId,
        address indexed user,
        uint256 amount,
        bool onTime,
        uint256 daysLate
    );
    event PositionLiquidated(
        uint256 indexed creditLineId,
        address indexed user,
        uint256 timestamp
    );

    modifier onlySolvencyVault() {
        require(msg.sender == solvencyVault, "Only SolvencyVault");
        _;
    }

    /**
     * @notice Initialize OAID
     */
    constructor() Ownable(msg.sender) {
        nextCreditLineId = 1;
    }

    /**
     * @notice Set SolvencyVault address (one-time)
     * @param _solvencyVault SolvencyVault contract address
     */
    function setSolvencyVault(address _solvencyVault) external onlyOwner {
        require(solvencyVault == address(0), "SolvencyVault already set");
        require(_solvencyVault != address(0), "Invalid address");
        solvencyVault = _solvencyVault;
    }

    /**
     * @notice Register user (called after KYC verification)
     * @param user User address to register
     */
    function registerUser(address user) external onlyOwner {
        require(user != address(0), "Invalid user address");
        require(!registeredUsers[user], "User already registered");

        registeredUsers[user] = true;
        userRegistrationTime[user] = block.timestamp;

        emit UserRegistered(user, block.timestamp);
    }

    /**
     * @notice Check if user is registered
     * @param user User address
     * @return bool Registration status
     */
    function isUserRegistered(address user) external view returns (bool) {
        return registeredUsers[user];
    }

    /**
     * @notice Issue credit line backed by collateral (only for registered users)
     * @param user Borrower address
     * @param collateralToken Token address
     * @param collateralAmount Token amount (18 decimals)
     * @param valueUSD Collateral value in USD (6 decimals)
     * @param solvencyPositionId SolvencyVault position ID
     * @return creditLineId Created credit line ID
     */
    function issueCreditLine(
        address user,
        address collateralToken,
        uint256 collateralAmount,
        uint256 valueUSD,
        uint256 solvencyPositionId
    ) external onlySolvencyVault nonReentrant returns (uint256 creditLineId) {
        require(registeredUsers[user], "User not registered");
        require(collateralToken != address(0), "Invalid token");
        require(collateralAmount > 0, "Amount must be > 0");
        require(valueUSD > 0, "Value must be > 0");

        // Calculate credit limit (70% of collateral value)
        uint256 creditLimit = (valueUSD * 7000) / 10000;

        creditLineId = _createCreditLine(
            user,
            collateralToken,
            collateralAmount,
            creditLimit,
            solvencyPositionId
        );
    }

    /**
     * @notice Update existing credit line when collateral value changes
     * @param creditLineId Credit line ID to update
     * @param newValueUSD New collateral value in USD (6 decimals)
     */
    function updateCreditLine(
        uint256 creditLineId,
        uint256 newValueUSD
    ) external onlySolvencyVault nonReentrant {
        CreditLine storage creditLine = creditLines[creditLineId];
        require(creditLine.active, "Credit line not active");
        require(newValueUSD > 0, "Value must be > 0");

        uint256 oldCreditLimit = creditLine.creditLimit;
        uint256 newCreditLimit = (newValueUSD * 7000) / 10000;

        creditLine.creditLimit = newCreditLimit;

        emit CreditLineUpdated(creditLineId, oldCreditLimit, newCreditLimit);
    }

    /**
     * @notice Internal function to create credit line
     */
    function _createCreditLine(
        address user,
        address collateralToken,
        uint256 collateralAmount,
        uint256 creditLimit,
        uint256 solvencyPositionId
    ) internal returns (uint256 creditLineId) {
        // Create credit line
        creditLineId = nextCreditLineId++;
        creditLines[creditLineId] = CreditLine({
            user: user,
            collateralToken: collateralToken,
            collateralAmount: collateralAmount,
            creditLimit: creditLimit,
            creditUsed: 0,
            solvencyPositionId: solvencyPositionId,
            issuedAt: block.timestamp,
            totalPayments: 0,
            onTimePayments: 0,
            latePayments: 0,
            totalAmountRepaid: 0,
            liquidated: false,
            liquidatedAt: 0,
            active: true
        });

        // Track user's credit lines
        userCreditLines[user].push(creditLineId);

        emit CreditLineIssued(
            creditLineId,
            user,
            collateralToken,
            collateralAmount,
            creditLimit,
            solvencyPositionId
        );
    }

    /**
     * @notice Record credit usage (called by external protocols)
     * @param creditLineId Credit line ID
     * @param amount Amount of credit used (6 decimals)
     */
    function recordCreditUsage(
        uint256 creditLineId,
        uint256 amount
    ) external onlySolvencyVault nonReentrant {
        CreditLine storage creditLine = creditLines[creditLineId];
        require(creditLine.active, "Credit line not active");
        require(amount > 0, "Amount must be > 0");

        uint256 availableCredit = creditLine.creditLimit - creditLine.creditUsed;
        require(amount <= availableCredit, "Exceeds available credit");

        creditLine.creditUsed += amount;

        emit CreditUsed(creditLineId, amount, creditLine.creditUsed);
    }

    /**
     * @notice Record credit repayment (called by external protocols)
     * @param creditLineId Credit line ID
     * @param amount Amount repaid (6 decimals)
     */
    function recordCreditRepayment(
        uint256 creditLineId,
        uint256 amount
    ) external onlySolvencyVault nonReentrant {
        CreditLine storage creditLine = creditLines[creditLineId];
        require(creditLine.active, "Credit line not active");
        require(amount > 0, "Amount must be > 0");
        require(amount <= creditLine.creditUsed, "Amount exceeds debt");

        creditLine.creditUsed -= amount;

        emit CreditRepaid(creditLineId, amount, creditLine.creditUsed);
    }

    /**
     * @notice Revoke credit line (called by SolvencyVault on liquidation)
     * @param creditLineId Credit line ID
     * @param reason Revocation reason
     */
    function revokeCreditLine(
        uint256 creditLineId,
        string memory reason
    ) external onlySolvencyVault nonReentrant {
        CreditLine storage creditLine = creditLines[creditLineId];
        require(creditLine.active, "Already revoked");

        creditLine.active = false;

        // Mark as liquidated if reason contains "liquidat"
        if (bytes(reason).length > 0 && _contains(reason, "liquidat")) {
            creditLine.liquidated = true;
            creditLine.liquidatedAt = block.timestamp;
            emit PositionLiquidated(creditLineId, creditLine.user, block.timestamp);
        }

        emit CreditLineRevoked(creditLineId, reason);
    }

    /**
     * @notice Record a payment made by user (called by SolvencyVault)
     * @param creditLineId Credit line ID
     * @param amount Amount paid (6 decimals)
     * @param onTime Whether payment was made on time
     * @param daysLate Number of days late (0 if on time)
     */
    function recordPayment(
        uint256 creditLineId,
        uint256 amount,
        bool onTime,
        uint256 daysLate
    ) external onlySolvencyVault nonReentrant {
        CreditLine storage creditLine = creditLines[creditLineId];
        require(creditLine.active, "Credit line not active");
        // Allow amount to be 0 for missed payments (where onTime is false)
        require(amount > 0 || !onTime, "Amount must be > 0 for on-time payments");

        // Update payment statistics
        creditLine.totalPayments++;
        creditLine.totalAmountRepaid += amount;

        if (onTime) {
            creditLine.onTimePayments++;
        } else {
            creditLine.latePayments++;
        }

        // Store payment record
        paymentHistory[creditLineId].push(PaymentRecord({
            timestamp: block.timestamp,
            amount: amount,
            onTime: onTime,
            daysLate: daysLate
        }));

        emit PaymentRecorded(creditLineId, creditLine.user, amount, onTime, daysLate);
    }

    /**
     * @notice Get available credit for credit line
     * @param creditLineId Credit line ID
     * @return Available credit in USD (6 decimals)
     */
    function getAvailableCredit(uint256 creditLineId) external view returns (uint256) {
        CreditLine memory creditLine = creditLines[creditLineId];
        if (!creditLine.active) return 0;

        return creditLine.creditLimit - creditLine.creditUsed;
    }

    /**
     * @notice Get all credit lines for user
     * @param user User address
     * @return Array of credit line IDs
     */
    function getUserCreditLines(address user) external view returns (uint256[] memory) {
        return userCreditLines[user];
    }

    /**
     * @notice Get credit line details
     * @param creditLineId Credit line ID
     * @return CreditLine struct
     */
    function getCreditLine(uint256 creditLineId) external view returns (CreditLine memory) {
        return creditLines[creditLineId];
    }

    /**
     * @notice Get total credit limit for user (across all active lines)
     * @param user User address
     * @return Total credit limit in USD (6 decimals)
     */
    function getTotalCreditLimit(address user) external view returns (uint256) {
        uint256 totalLimit = 0;
        uint256[] memory lineIds = userCreditLines[user];

        for (uint256 i = 0; i < lineIds.length; i++) {
            CreditLine memory line = creditLines[lineIds[i]];
            if (line.active) {
                totalLimit += line.creditLimit;
            }
        }

        return totalLimit;
    }

    /**
     * @notice Get total available credit for user
     * @param user User address
     * @return Total available credit in USD (6 decimals)
     */
    function getTotalAvailableCredit(address user) external view returns (uint256) {
        uint256 totalAvailable = 0;
        uint256[] memory lineIds = userCreditLines[user];

        for (uint256 i = 0; i < lineIds.length; i++) {
            CreditLine memory line = creditLines[lineIds[i]];
            if (line.active) {
                totalAvailable += (line.creditLimit - line.creditUsed);
            }
        }

        return totalAvailable;
    }

    /**
     * @notice Get payment history for a credit line
     * @param creditLineId Credit line ID
     * @return Array of payment records
     */
    function getPaymentHistory(uint256 creditLineId) external view returns (PaymentRecord[] memory) {
        return paymentHistory[creditLineId];
    }

    /**
     * @notice Calculate credit score for user (0-1000)
     * @param user User address
     * @return Credit score based on payment history
     */
    function getCreditScore(address user) external view returns (uint256) {
        uint256[] memory lineIds = userCreditLines[user];
        if (lineIds.length == 0) return 0;

        uint256 totalPayments = 0;
        uint256 totalOnTime = 0;
        uint256 totalLiquidations = 0;

        for (uint256 i = 0; i < lineIds.length; i++) {
            CreditLine memory line = creditLines[lineIds[i]];
            totalPayments += line.totalPayments;
            totalOnTime += line.onTimePayments;
            if (line.liquidated) {
                totalLiquidations++;
            }
        }

        // No payment history = neutral score of 500
        if (totalPayments == 0) return 500;

        // Base score from payment ratio (0-800 points)
        uint256 paymentScore = (totalOnTime * 800) / totalPayments;

        // Penalty for liquidations (-200 points per liquidation, max -400)
        uint256 liquidationPenalty = totalLiquidations * 200;
        if (liquidationPenalty > 400) liquidationPenalty = 400;

        // Bonus for high number of on-time payments (up to +200 points)
        uint256 volumeBonus = totalOnTime > 10 ? 200 : (totalOnTime * 20);

        // Calculate final score (0-1000)
        uint256 score = paymentScore + volumeBonus;
        if (score > liquidationPenalty) {
            score -= liquidationPenalty;
        } else {
            score = 0;
        }

        if (score > 1000) score = 1000;

        return score;
    }

    /**
     * @notice Get credit profile summary for user
     * @param user User address
     * @return activeCreditLines Number of active credit lines
     * @return totalCreditLimit Total credit limit
     * @return totalPayments Total payments made
     * @return onTimePayments On-time payments
     * @return latePayments Late payments
     * @return liquidations Number of liquidated positions
     * @return creditScore Credit score (0-1000)
     */
    function getCreditProfile(address user) external view returns (
        uint256 activeCreditLines,
        uint256 totalCreditLimit,
        uint256 totalPayments,
        uint256 onTimePayments,
        uint256 latePayments,
        uint256 liquidations,
        uint256 creditScore
    ) {
        uint256[] memory lineIds = userCreditLines[user];

        for (uint256 i = 0; i < lineIds.length; i++) {
            CreditLine memory line = creditLines[lineIds[i]];
            if (line.active) {
                activeCreditLines++;
                totalCreditLimit += line.creditLimit;
            }
            totalPayments += line.totalPayments;
            onTimePayments += line.onTimePayments;
            latePayments += line.latePayments;
            if (line.liquidated) {
                liquidations++;
            }
        }

        // Calculate credit score
        creditScore = this.getCreditScore(user);
    }

    /**
     * @notice Helper function to check if string contains substring
     * @param str String to search in
     * @param substr Substring to search for
     * @return bool Whether substring is found
     */
    function _contains(string memory str, string memory substr) internal pure returns (bool) {
        bytes memory strBytes = bytes(str);
        bytes memory substrBytes = bytes(substr);

        if (substrBytes.length > strBytes.length) return false;
        if (substrBytes.length == 0) return false;

        for (uint256 i = 0; i <= strBytes.length - substrBytes.length; i++) {
            bool found = true;
            for (uint256 j = 0; j < substrBytes.length; j++) {
                if (strBytes[i + j] != substrBytes[j]) {
                    found = false;
                    break;
                }
            }
            if (found) return true;
        }

        return false;
    }
}

