// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "../core/IdentityRegistry.sol";

/**
 * @title SecondaryMarket
 * @notice Trustless P2P Orderbook Exchange for RWA Tokens
 * @dev Supports Limit Orders (Maker) and Market Fills (Taker) with partial fills.
 */
contract SecondaryMarket is ReentrancyGuard, Ownable {
    using SafeERC20 for IERC20;

    struct Order {
        uint256 id;
        address maker;
        address tokenAddress;
        uint256 amount;        // Remaining amount of RWA tokens to buy/sell
        uint256 pricePerToken; // USDC per 1e18 RWA tokens (1:1 ratio = 1e6 USDC)
        bool isBuy;            // true = Bid (Buy RWA), false = Ask (Sell RWA)
        bool isActive;
    }

    IERC20 public usdc;
    IdentityRegistry public identityRegistry;

    uint256 public nextOrderId;
    mapping(uint256 => Order) public orders;

    // Events optimized for Indexer
    event OrderCreated(
        uint256 indexed orderId,
        address indexed maker,
        address indexed tokenAddress,
        uint256 amount,
        uint256 pricePerToken,
        bool isBuy,
        uint256 timestamp
    );

    event OrderFilled(
        uint256 indexed orderId,
        address indexed taker,
        address indexed maker,
        address tokenAddress,
        uint256 amountFilled,
        uint256 totalCost,
        uint256 remainingAmount,
        uint256 timestamp
    );

    event OrderCancelled(
        uint256 indexed orderId,
        address indexed maker,
        uint256 timestamp
    );

    event OrderSettledForYield(
        uint256 indexed orderId,
        address indexed maker,
        uint256 settledAmount,
        bool isYieldClaim
    );

    constructor(address _usdc, address _identityRegistry) Ownable(msg.sender) {
        usdc = IERC20(_usdc);
        identityRegistry = IdentityRegistry(_identityRegistry);
    }

    /**
     * @notice Create a Limit Order
     * @param tokenAddress The RWA token address
     * @param amount Amount of RWA tokens to trade (in wei)
     * @param pricePerToken Price in USDC (6 decimals) for 1e18 RWA tokens
     * @param isBuy True for Buy Limit (Bid), False for Sell Limit (Ask)
     */
    function createOrder(
        address tokenAddress,
        uint256 amount,
        uint256 pricePerToken,
        bool isBuy
    ) external nonReentrant {
        require(amount > 0, "Amount must be > 0");
        require(pricePerToken > 0, "Price must be > 0");
        require(identityRegistry.isVerified(msg.sender), "Maker not verified");

        if (isBuy) {
            // BUY ORDER: Maker locks USDC
            // Total USDC needed = (amount * pricePerToken) / 1e18
            uint256 totalUsdc = (amount * pricePerToken) / 1e18;
            require(totalUsdc > 0, "Total value too low");
            usdc.safeTransferFrom(msg.sender, address(this), totalUsdc);
        } else {
            // SELL ORDER: Maker locks RWA Token
            IERC20(tokenAddress).safeTransferFrom(msg.sender, address(this), amount);
        }

        uint256 orderId = nextOrderId++;
        orders[orderId] = Order({
            id: orderId,
            maker: msg.sender,
            tokenAddress: tokenAddress,
            amount: amount,
            pricePerToken: pricePerToken,
            isBuy: isBuy,
            isActive: true
        });

        emit OrderCreated(orderId, msg.sender, tokenAddress, amount, pricePerToken, isBuy, block.timestamp);
    }

    /**
     * @notice Fill an active order (Partial fills allowed)
     * @param orderId The ID of the order to fill
     * @param amountToFill Amount of RWA tokens to fill
     */
    function fillOrder(uint256 orderId, uint256 amountToFill) external nonReentrant {
        Order storage order = orders[orderId];
        require(order.isActive, "Order not active");
        require(amountToFill > 0, "Fill amount must be > 0");
        require(amountToFill <= order.amount, "Fill amount exceeds available");
        require(msg.sender != order.maker, "Cannot fill own order");
        require(identityRegistry.isVerified(msg.sender), "Taker not verified");

        // Calculate Cost in USDC
        // pricePerToken is USDC (6 decimals) per 1e18 RWA
        uint256 costInUsdc = (amountToFill * order.pricePerToken) / 1e18;
        require(costInUsdc > 0, "Trade value too low");

        if (order.isBuy) {
            // FILLING A BUY ORDER (Selling into a Bid)
            // Maker: Buyer (Locked USDC) | Taker: Seller (Sends RWA)

            // 1. Taker (Seller) sends RWA to Maker (Buyer)
            IERC20(order.tokenAddress).safeTransferFrom(msg.sender, order.maker, amountToFill);

            // 2. Contract releases USDC to Taker (Seller)
            usdc.safeTransfer(msg.sender, costInUsdc);

        } else {
            // FILLING A SELL ORDER (Buying from an Ask)
            // Maker: Seller (Locked RWA) | Taker: Buyer (Sends USDC)

            // 1. Taker (Buyer) sends USDC to Maker (Seller)
            usdc.safeTransferFrom(msg.sender, order.maker, costInUsdc);

            // 2. Contract releases RWA to Taker (Buyer)
            IERC20(order.tokenAddress).safeTransfer(msg.sender, amountToFill);
        }

        // Update State
        order.amount -= amountToFill;
        if (order.amount == 0) {
            order.isActive = false;
        }

        emit OrderFilled(
            orderId, 
            msg.sender, 
            order.maker, 
            order.tokenAddress, 
            amountToFill, 
            costInUsdc, 
            order.amount, 
            block.timestamp
        );
    }

    /**
     * @notice Cancel an active order
     * @param orderId The ID of the order to cancel
     */
    function cancelOrder(uint256 orderId) external nonReentrant {
        Order storage order = orders[orderId];
        require(order.maker == msg.sender, "Not maker");
        require(order.isActive, "Order not active");

        order.isActive = false;

        if (order.isBuy) {
            // Refund remaining USDC
            uint256 refundUsdc = (order.amount * order.pricePerToken) / 1e18;
            if (refundUsdc > 0) {
                usdc.safeTransfer(msg.sender, refundUsdc);
            }
        } else {
            // Refund remaining RWA
            if (order.amount > 0) {
                IERC20(order.tokenAddress).safeTransfer(msg.sender, order.amount);
            }
        }

        emit OrderCancelled(orderId, msg.sender, block.timestamp);
    }

    /**
     * @notice Admin function to settle orders during yield distribution
     * @param yieldVault Address of the YieldVault contract
     * @param tokenAddress Address of the RWA token
     * @param orderIds List of order IDs to settle
     */
    function settleYield(
        address yieldVault,
        address tokenAddress,
        uint256[] calldata orderIds
    ) external onlyOwner nonReentrant {
        require(yieldVault != address(0), "Invalid YieldVault");

        for (uint256 i = 0; i < orderIds.length; i++) {
            Order storage order = orders[orderIds[i]];

            // Skip if not active or token mismatch
            if (!order.isActive || order.tokenAddress != tokenAddress) {
                continue;
            }

            order.isActive = false;

            if (order.isBuy) {
                // BUY ORDER: Refund locked USDC
                uint256 refundUsdc = (order.amount * order.pricePerToken) / 1e18;
                if (refundUsdc > 0) {
                    usdc.safeTransfer(order.maker, refundUsdc);
                }

                emit OrderSettledForYield(order.id, order.maker, refundUsdc, false);
            } else {
                // SELL ORDER: Burn RWA for Yield (USDC)
                if (order.amount > 0) {
                    // Approve YieldVault
                    IERC20(tokenAddress).approve(yieldVault, order.amount);

                    // Record USDC balance before
                    uint256 balanceBefore = usdc.balanceOf(address(this));

                    // Call claimYield
                    (bool success, ) = yieldVault.call(
                        abi.encodeWithSignature("claimYield(address,uint256)", tokenAddress, order.amount)
                    );
                    require(success, "Yield claim failed");

                    // Calculate yield received
                    uint256 yieldReceived = usdc.balanceOf(address(this)) - balanceBefore;

                    // Transfer yield to maker
                    if (yieldReceived > 0) {
                        usdc.safeTransfer(order.maker, yieldReceived);
                    }

                    emit OrderSettledForYield(order.id, order.maker, yieldReceived, true);
                }
            }
        }
    }
}

contracts/test/MockArbitrumDEX.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

/**
 * @title MockArbitrumDEX
 * @notice Mock DEX for testing stARB ↔ USDC swaps on Arbitrum
 * @dev Simulates an AMM with configurable exchange rates for demo scenarios
 *
 * Features:
 * - Swap stARB for USDC (and vice versa)
 * - Configurable exchange rate for demo
 * - Slippage simulation
 * - Liquidity tracking
 */
contract MockArbitrumDEX is Ownable, ReentrancyGuard {
    IERC20 public stARB;
    IERC20 public USDC;

    // Exchange rate: 1 stARB = X USDC (with 6 decimals to match USDC)
    // Example: 0.8 * 1e6 = 800000 USDC per stARB
    uint256 public exchangeRate;

    // Liquidity reserves
    uint256 public stARBReserve;
    uint256 public usdcReserve;

    // Events
    event ExchangeRateUpdated(uint256 oldRate, uint256 newRate);
    event Swapped(
        address indexed user,
        address indexed tokenIn,
        address indexed tokenOut,
        uint256 amountIn,
        uint256 amountOut
    );
    event LiquidityAdded(uint256 stARBAmount, uint256 usdcAmount);

    /**
     * @notice Initialize Mock Arbitrum DEX
     * @param _stARB MockStARB token address
     * @param _USDC USDC token address
     * @param _initialExchangeRate Initial exchange rate (USDC per stARB, 6 decimals)
     */
    constructor(
        address _stARB,
        address _USDC,
        uint256 _initialExchangeRate
    ) Ownable(msg.sender) {
        stARB = IERC20(_stARB);
        USDC = IERC20(_USDC);
        exchangeRate = _initialExchangeRate;
        emit ExchangeRateUpdated(0, _initialExchangeRate);
    }

    /**
     * @notice Set exchange rate (for demo scenarios)
     * @param newRate New exchange rate (USDC per stARB, 6 decimals)
     */
    function setExchangeRate(uint256 newRate) external onlyOwner {
        require(newRate > 0, "Rate must be greater than 0");
        uint256 oldRate = exchangeRate;
        exchangeRate = newRate;
        emit ExchangeRateUpdated(oldRate, newRate);
    }

    /**
     * @notice Get quote for stARB → USDC swap
     * @param stARBAmount Amount of stARB to swap (18 decimals)
     * @return Expected USDC output (6 decimals)
     */
    function getQuote(uint256 stARBAmount) external view returns (uint256) {
        // Convert stARB (18 decimals) to USDC (6 decimals) using exchange rate
        return (stARBAmount * exchangeRate) / 1e18;
    }

    /**
     * @notice Get quote for USDC → stARB swap
     * @param usdcAmount Amount of USDC to swap (6 decimals)
     * @return Expected stARB output (18 decimals)
     */
    function getQuoteReverse(uint256 usdcAmount) external view returns (uint256) {
        // Convert USDC (6 decimals) to stARB (18 decimals) using exchange rate
        return (usdcAmount * 1e18) / exchangeRate;
    }

    /**
     * @notice Swap stARB for USDC
     * @param stARBAmount Amount of stARB to swap (18 decimals)
     * @param minUSDCOut Minimum USDC output (slippage protection, 6 decimals)
     * @return usdcOut Actual USDC output
     */
    function swapStARBForUSDC(
        uint256 stARBAmount,
        uint256 minUSDCOut
    ) external nonReentrant returns (uint256 usdcOut) {
        require(stARBAmount > 0, "Amount must be greater than 0");

        // Calculate USDC output
        usdcOut = (stARBAmount * exchangeRate) / 1e18;
        require(usdcOut >= minUSDCOut, "Slippage tolerance exceeded");
        require(usdcReserve >= usdcOut, "Insufficient USDC liquidity");

        // Transfer stARB from user to DEX
        require(
            stARB.transferFrom(msg.sender, address(this), stARBAmount),
            "stARB transfer failed"
        );

        // Update reserves
        stARBReserve += stARBAmount;
        usdcReserve -= usdcOut;

        // Transfer USDC to user
        require(USDC.transfer(msg.sender, usdcOut), "USDC transfer failed");

        emit Swapped(msg.sender, address(stARB), address(USDC), stARBAmount, usdcOut);
    }

    /**
     * @notice Swap USDC for stARB
     * @param usdcAmount Amount of USDC to swap (6 decimals)
     * @param minStARBOut Minimum stARB output (slippage protection, 18 decimals)
     * @return stARBOut Actual stARB output
     */
    function swapUSDCForStARB(
        uint256 usdcAmount,
        uint256 minStARBOut
    ) external nonReentrant returns (uint256 stARBOut) {
        require(usdcAmount > 0, "Amount must be greater than 0");

        // Calculate stARB output
        stARBOut = (usdcAmount * 1e18) / exchangeRate;
        require(stARBOut >= minStARBOut, "Slippage tolerance exceeded");
        require(stARBReserve >= stARBOut, "Insufficient stARB liquidity");

        // Transfer USDC from user to DEX
        require(
            USDC.transferFrom(msg.sender, address(this), usdcAmount),
            "USDC transfer failed"
        );

        // Update reserves
        usdcReserve += usdcAmount;
        stARBReserve -= stARBOut;

        // Transfer stARB to user
        require(stARB.transfer(msg.sender, stARBOut), "stARB transfer failed");

        emit Swapped(msg.sender, address(USDC), address(stARB), usdcAmount, stARBOut);
    }

    /**
     * @notice Swap exact stARB for exact USDC (backend calculates amounts)
     * @dev This is the preferred method - backend calculates exchange rate off-chain using historical data
     * @param stARBAmount Exact amount of stARB to swap (18 decimals)
     * @param exactUSDCOut Exact amount of USDC to receive (6 decimals) - calculated by backend
     * @return usdcOut Actual USDC output (should match exactUSDCOut)
     */
    function swapStARBForUSDCExact(
        uint256 stARBAmount,
        uint256 exactUSDCOut
    ) external nonReentrant returns (uint256 usdcOut) {
        require(stARBAmount > 0, "stARB amount must be greater than 0");
        require(exactUSDCOut > 0, "USDC amount must be greater than 0");
        require(usdcReserve >= exactUSDCOut, "Insufficient USDC liquidity");

        // Transfer stARB from user to DEX
        require(
            stARB.transferFrom(msg.sender, address(this), stARBAmount),
            "stARB transfer failed"
        );

        // Update reserves
        stARBReserve += stARBAmount;
        usdcReserve -= exactUSDCOut;

        // Transfer exact USDC to user
        require(USDC.transfer(msg.sender, exactUSDCOut), "USDC transfer failed");

        emit Swapped(msg.sender, address(stARB), address(USDC), stARBAmount, exactUSDCOut);
        return exactUSDCOut;
    }

    /**
     * @notice Swap exact USDC for exact stARB (backend calculates amounts)
     * @dev This is the preferred method - backend calculates exchange rate off-chain using historical data
     * @param usdcAmount Exact amount of USDC to swap (6 decimals)
     * @param exactStARBOut Exact amount of stARB to receive (18 decimals) - calculated by backend
     * @return stARBOut Actual stARB output (should match exactStARBOut)
     */
    function swapUSDCForStARBExact(
        uint256 usdcAmount,
        uint256 exactStARBOut
    ) external nonReentrant returns (uint256 stARBOut) {
        require(usdcAmount > 0, "USDC amount must be greater than 0");
        require(exactStARBOut > 0, "stARB amount must be greater than 0");
        require(stARBReserve >= exactStARBOut, "Insufficient stARB liquidity");

        // Transfer USDC from user to DEX
        require(
            USDC.transferFrom(msg.sender, address(this), usdcAmount),
            "USDC transfer failed"
        );

        // Update reserves
        usdcReserve += usdcAmount;
        stARBReserve -= exactStARBOut;

        // Transfer exact stARB to user
        require(stARB.transfer(msg.sender, exactStARBOut), "stARB transfer failed");

        emit Swapped(msg.sender, address(USDC), address(stARB), usdcAmount, exactStARBOut);
        return exactStARBOut;
    }

    /**
     * @notice Add liquidity to DEX (for testing)
     * @param stARBAmount Amount of stARB to add
     * @param usdcAmount Amount of USDC to add
     */
    function addLiquidity(uint256 stARBAmount, uint256 usdcAmount) external onlyOwner {
        if (stARBAmount > 0) {
            require(
                stARB.transferFrom(msg.sender, address(this), stARBAmount),
                "stARB transfer failed"
            );
            stARBReserve += stARBAmount;
        }

        if (usdcAmount > 0) {
            require(
                USDC.transferFrom(msg.sender, address(this), usdcAmount),
                "USDC transfer failed"
            );
            usdcReserve += usdcAmount;
        }

        emit LiquidityAdded(stARBAmount, usdcAmount);
    }

    /**
     * @notice Get current reserves
     * @return stARB reserve and USDC reserve
     */
    function getReserves() external view returns (uint256, uint256) {
        return (stARBReserve, usdcReserve);
    }
}

contracts/test/MockStARB.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";

/**
 * @title MockStARB
 * @notice Mock Staked ARB token for testing and demo purposes on Arbitrum
 * @dev Simple ERC20 token - price is managed off-chain in backend
 *
 * Features:
 * - Standard ERC20 token
 * - Public mint function for testing
 * - No on-chain price oracle (backend manages historical price data)
 * - Simulates Arbitrum liquid staking yield (~8% APY from sequencer fees)
 */
contract MockStARB is ERC20, Ownable {
    // Events
    event TokensMinted(address indexed to, uint256 amount);

    /**
     * @notice Initialize MockStARB token
     */
    constructor() ERC20("Staked ARB", "stARB") Ownable(msg.sender) {
        // Mint 10M stARB to deployer for liquidity provisioning
        _mint(msg.sender, 10_000_000 * 10 ** 18);
    }

    /**
     * @notice Mint stARB tokens (for testing)
     * @dev Public function to allow easy testing
     * @param to Recipient address
     * @param amount Amount to mint (with 18 decimals)
     */
    function mint(address to, uint256 amount) external {
        _mint(to, amount);
        emit TokensMinted(to, amount);
    }

    /**
     * @notice Burn stARB tokens
     * @param amount Amount to burn (with 18 decimals)
     */
    function burn(uint256 amount) external {
        _burn(msg.sender, amount);
    }

    /**
     * @notice Decimals for stARB (standard 18)
     */
    function decimals() public pure override returns (uint8) {
        return 18;
    }
}

contracts/test/MockUSDC.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/ERC20.sol";

/**
 * @title MockUSDC
 * @notice Mock USDC token for testing purposes
 */
contract MockUSDC is ERC20 {
    uint8 private _decimals = 6;

    constructor() ERC20("USD Coin", "USDC") {
        // Mint 100 billion USDC to deployer for testing
        _mint(msg.sender, 100_000_000_000 * 10 ** _decimals);
    }

    function decimals() public view virtual override returns (uint8) {
        return _decimals;
    }

    function mint(address to, uint256 amount) external {
        _mint(to, amount);
    }

    function faucet() external {
        // Faucet: 1000 USDC per call
        _mint(msg.sender, 1000 * 10 ** _decimals);
    }
}

